<template>
  <div class="clusters-layout-frame">
  <div class="kvm-page clusters-page">
    <header class="clusters-header">
      <div><span class="eyebrow">{{ t('clusters.eyebrow') }}</span><h1>{{ t('clusters.title') }}</h1><p>{{ t('clusters.subtitle') }}</p></div>
      <div class="cluster-heading-actions"><button class="btn role-primary" @click="openManagedKvmClusters">{{ t('clusters.managedKvmClusters') }}</button><button class="btn role-secondary" :disabled="loading || readinessLoading || refreshingStale" @click="load">{{ loading || readinessLoading || refreshingStale ? t('clusters.refreshing') : t('clusters.refresh') }}</button></div>
    </header>

    <div v-if="error" class="banner error" role="alert">{{ error }}</div>
    <div v-if="readinessLoading" class="inline-callout info" role="status" aria-live="polite">{{ t('clusters.loadingReadinessProgressive') }}</div>
    <div v-if="readinessError" class="inline-callout warning" role="alert">{{ t('clusters.readinessRefreshFailed') }} {{ readinessError }}</div>
    <div v-if="virtualDomainOperationJobId" class="inline-callout info" role="status" aria-live="polite"><strong>{{ t('clusters.vmPrepareOperationTitle') }}</strong><p>{{ t('clusters.vmPrepareOperationStatus', { status: operationStatusText(virtualDomainOperationStatus || 'running'), id: virtualDomainOperationJobId }) }}</p><button class="btn role-secondary btn-sm" :disabled="virtualDomainPrepareBusy" @click="resumeVirtualDomainOperation">{{ t('clusters.refreshOperation') }}</button></div>
    <div v-if="virtualDomainOperationError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.vmPrepareBlocked') }}</strong><p>{{ virtualDomainOperationError }}</p></div>
    <div v-if="virtualDomainPrepareResult" class="inline-callout success" role="status"><strong>{{ t('clusters.vmPrepareSucceeded') }}</strong><p>{{ t('clusters.vmPrepareResult', { id: virtualDomainPrepareResult.resource_id, path: virtualDomainPrepareResult.config_path }) }}</p><small>{{ t('clusters.vmPrepareStoppedNote') }}</small></div>
    <div v-if="loading && !loaded" class="loading">{{ t('clusters.loading') }}</div>
    <template v-else>
      <div class="cluster-stats">
        <article><span>{{ t('clusters.registeredHosts') }}</span><strong>{{ hosts.length }}</strong></article>
        <article><span>{{ t('clusters.haEnabledHosts') }}</span><strong>{{ haEnabledCount }}</strong><small>{{ t('clusters.haEnabledHostsHelp') }}</small></article>
        <article><span>{{ t('clusters.clusterHosts') }}</span><strong>{{ clusterHostCount }}</strong><small>{{ t('clusters.clusterHostsHelp') }}</small></article>
            </div>

      <nav class="cluster-nav" role="tablist" :aria-label="t('clusters.navigation')">
        <button v-for="(section, index) in availableSections" :id="`cluster-tab-${section}`" :key="section" class="cluster-nav-item" role="tab" :tabindex="activeSection === section ? 0 : -1" :aria-selected="activeSection === section" :aria-controls="activeSection === section ? `cluster-panel-${section}` : undefined" @click="selectSection(section)" @keydown="onNavigationKeydown($event, index)">
          <span class="nav-icon" aria-hidden="true">{{ sectionIcon(section) }}</span>{{ t(`clusters.section_${section}`) }}
          <span v-if="section === 'nodes'" class="nav-count">{{ hosts.length }}</span>
        </button>
      </nav>
      <label class="cluster-mobile-picker"><span>{{ t('clusters.navigation') }}</span><select :value="activeSection" @change="selectSectionFromPicker"><option v-for="section in availableSections" :key="section" :value="section">{{ t(`clusters.section_${section}`) }}</option></select></label>
      <div v-if="!clusterStatus && !clusterStatusLoading" class="inline-callout info live-cluster-guidance" role="status">{{ t('clusters.liveClusterAreasHint') }}</div>

      <section v-if="activeSection === 'clusters'" id="cluster-panel-clusters" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t('clusters.inventoryTitle') }}</h2><p>{{ t('clusters.inventoryDescription') }}</p></div><button class="btn role-primary" @click="startNewPlan">{{ t('clusters.startPlanning') }}</button></div>
        <section class="host-ha-tools" aria-labelledby="host-ha-tools-title">
          <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.readiness') }}</span><h2 id="host-ha-tools-title">{{ t('clusters.haToolsPanelTitle') }}</h2><p>{{ t('clusters.haToolsPanelHelp') }}</p></div><div class="cluster-heading-actions"><button class="btn role-primary btn-sm" :disabled="!canManageCluster || !haToolsEligibleHosts.length || haToolsBatchLoading || haToolBusyHostIds.length > 0" :title="!canManageCluster ? t('clusters.operatorRoleRequired') : !haToolsEligibleHosts.length ? t('clusters.haToolsNoEligibleHelp') : ''" @click="installHaToolsForEligibleHosts">{{ haToolsBatchLoading ? t('clusters.haToolsBatchInstalling') : haToolsEligibleHosts.length ? t('clusters.enableHaToolsBatch', { count: haToolsEligibleHosts.length }) : t('clusters.haToolsNoEligible') }}</button><button class="btn role-link btn-sm" @click="activeSection = 'overview'">{{ t('clusters.viewHostReadiness') }}</button></div></div>
          <div class="inline-callout info readiness-sequence"><strong>{{ t('clusters.readinessSequenceTitle') }}</strong><ol><li>{{ t('clusters.readinessAddon') }}</li><li>{{ t('clusters.readinessTools') }}</li><li>{{ t('clusters.readinessConfigure') }}</li><li>{{ t('clusters.readinessVerify') }}</li></ol></div>
          <div v-if="!hosts.length" class="inline-callout info"><strong>{{ t('clusters.noHosts') }}</strong><p>{{ t('clusters.noHostsHelp') }}</p></div>
          <div v-else class="table-wrap"><table class="table"><thead><tr><th>{{ t('clusters.host') }}</th><th>{{ t('clusters.haAddon') }}</th><th>{{ t('clusters.clusterStack') }}</th><th>{{ t('clusters.operations') }}</th></tr></thead><tbody>
            <tr v-for="host in hosts" :key="`ha-tools-${host.id}`">
              <td><strong>{{ host.hostname || host.name }}</strong><small>{{ host.address }}:{{ host.port }}</small></td>
              <td><span class="state" :class="haClass(host)"><i></i>{{ haLabel(host) }}</span><small v-if="host.ha?.ha_product">{{ host.ha.ha_product }}</small><small v-else-if="host.ha?.inspection_error">{{ host.ha.inspection_error }}</small></td>
              <td><div class="stack-status"><span :class="serviceClass(host,'pacemaker')">{{ t('clusters.pacemaker') }}: {{ serviceLabel(host,'pacemaker') }}</span><span :class="serviceClass(host,'corosync')">{{ t('clusters.corosync') }}: {{ serviceLabel(host,'corosync') }}</span><span :class="serviceClass(host,'hawk')">{{ t('clusters.hawk') }}: {{ serviceLabel(host,'hawk') }}</span></div></td>
              <td class="action-cell"><div class="cell-action-controls"><span v-if="host.ha?.ha_active && haToolsInstalled(host)" class="state ready ha-tools-state"><i></i>{{ t('clusters.haToolsInstalled') }}</span><button v-else-if="host.ha?.ha_active" class="btn role-primary btn-sm" :disabled="!canManageCluster || haToolBusyHostIds.includes(host.id)" :title="!canManageCluster ? t('clusters.operatorRoleRequired') : ''" @click="installHaTools(host)">{{ haToolBusyHostIds.includes(host.id) ? t('clusters.haToolsInstalling') : t('clusters.enableHaTools') }}</button><span v-else-if="host.ha?.ha_available">{{ t('clusters.activateHaAddonFirst') }}</span><span v-else>{{ t('clusters.haUnavailable') }}</span><div v-if="haToolResults[host.id]" class="ha-tool-result" :class="haToolResults[host.id].status" role="status" aria-live="polite"><span>{{ haToolResults[host.id].message || haToolResults[host.id].error || operationStatusText(haToolResults[host.id].status) }}</span><small v-if="haToolResults[host.id].status === 'installed'">{{ t('clusters.serviceActivationGuide') }}</small></div></div></td>
            </tr>
          </tbody></table></div>
          <div v-if="!canManageCluster" class="inline-callout info"><strong>{{ t('clusters.readOnly') }}</strong><p>{{ t('clusters.operatorRoleRequired') }}</p></div>
        </section>
          <div v-if="clusterHostCount === 0 && !managedSuseHaClusters.length" class="empty-state"><div class="preview-icon" aria-hidden="true">◇</div><h3>{{ t('clusters.noClusters') }}</h3><p>{{ t('clusters.noClustersHelp') }}</p><button class="btn role-primary" @click="activeSection = 'plan'">{{ t('clusters.planFirstCluster') }}</button></div>
        <section v-if="managedSuseHaClusters.length" class="saved-plans" aria-labelledby="managed-ha-clusters-title">
          <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.liveStatus') }}</span><h2 id="managed-ha-clusters-title">{{ t('clusters.managedHaClustersTitle') }}</h2><p>{{ t('clusters.managedHaClustersHelp') }}</p></div></div>
          <div class="saved-plan-list"><article v-for="cluster in managedSuseHaClusters" :key="cluster.id" class="cluster-source-card">
            <div><strong>{{ cluster.name }}</strong><small>{{ t('clusters.managedHaClusterMembers', { members: cluster.members.map((member) => member.name).join(', ') || '—' }) }}</small><small>{{ t('clusters.managedHaClusterChecked', { date: dateLabel(cluster.last_checked_at) }) }}</small><span class="state" :class="clusterSourceHost(cluster) ? 'ready' : 'warning-state'"><i></i>{{ t(clusterSourceHost(cluster) ? 'clusters.managedHaClusterLive' : 'clusters.managedHaClusterUnavailableShort') }}</span></div>
            <div class="cluster-heading-actions"><button class="btn role-secondary btn-sm" :disabled="!clusterSourceHost(cluster) || registeringClusterHostId !== ''" :title="clusterSourceHost(cluster) ? '' : t('clusters.managedHaClusterUnavailable')" @click="syncManagedSuseHaCluster(cluster)">{{ registeringClusterHostId === clusterSourceHost(cluster)?.id ? t('clusters.registeringHaCluster') : t('clusters.syncHaClusterMembership') }}</button><button class="btn role-primary btn-sm" :disabled="!clusterSourceHost(cluster) || clusterStatusLoading" :title="clusterSourceHost(cluster) ? '' : t('clusters.managedHaClusterUnavailable')" @click="openManagedSuseHaCluster(cluster)">{{ t('clusters.openCluster') }}</button></div>
          </article></div>
        </section>
        <section class="saved-plans" aria-labelledby="saved-plans-title">
          <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.planning') }}</span><h2 id="saved-plans-title">{{ t('clusters.savedPlansTitle') }}</h2><p>{{ t('clusters.savedPlansHelp') }}</p></div><button v-if="canManageCluster" class="btn role-secondary btn-sm" @click="startNewPlan">{{ t('clusters.newPlan') }}</button></div>
          <div v-if="plansLoading" class="loading compact">{{ t('clusters.plansLoading') }}</div>
          <div v-else-if="plansError" class="inline-callout warning" role="alert">{{ plansError }}</div>
          <div v-else-if="!clusterPlans.length" class="inline-callout info">{{ t('clusters.noSavedPlans') }}</div>
          <div v-else class="saved-plan-list">
            <article v-for="plan in clusterPlans" :key="plan.id" class="saved-plan-card">
              <div class="saved-plan-main"><span class="state warning-state"><i></i>{{ t('clusters.draftState') }}</span><strong>{{ plan.name || t('clusters.unnamedPlan') }}</strong><small>{{ t(`clusters.savedPlanType_${plan.cluster_type}`) }} · {{ plan.host_ids.length }} {{ t('clusters.selectedNodes') }} · {{ dateLabel(plan.updated_at) }}</small><small>{{ t('clusters.preflightRequiredOnResume') }}</small><small>{{ t('clusters.corosyncPlanTitle') }} · ring0 {{ plan.config.corosync_networks?.[0] || t('clusters.corosyncNetworkNoSelection') }} · ring1 {{ plan.config.corosync_networks?.[1] || t('clusters.corosyncNoSecondChannel') }}</small><small>{{ plan.config.corosync_network_reviewed ? t('clusters.corosyncNetworkPreviouslyReviewed') : t('clusters.corosyncNetworkNotReviewed') }}</small></div>
              <div class="cluster-heading-actions"><button class="btn role-primary btn-sm" :disabled="!canManageCluster" @click="resumeClusterPlan(plan)">{{ t('clusters.resumePlan') }}</button><button class="btn role-danger btn-sm" :disabled="!canManageCluster || planBusyId === plan.id" @click="deleteClusterPlan(plan)">{{ planBusyId === plan.id ? t('clusters.deletingPlan') : t('clusters.deletePlan') }}</button></div>
            </article>
          </div>
        </section>
        <template v-if="clusterHostCount > 0">
          <div v-if="unregisteredClusterHosts.length" class="cluster-source-list"><article v-for="host in unregisteredClusterHosts" :key="host.ha?.cluster_identity || host.id" class="cluster-source-card"><div><strong>{{ host.ha?.cluster_name || host.hostname || host.name }}</strong><small>{{ t('clusters.reportedBy', { host: host.hostname || host.name }) }}</small><small v-if="host.ha?.cluster_members?.length">{{ t('clusters.confirmedMembers', { members: host.ha.cluster_members.join(', ') }) }}</small><span class="state ready"><i></i>{{ t('clusters.clusterDetected') }}</span></div><div class="cluster-heading-actions"><button v-if="canManageCluster" class="btn role-secondary btn-sm" :disabled="registeringClusterHostId === host.id" @click="registerSuseHaCluster(host)">{{ registeringClusterHostId === host.id ? t('clusters.registeringHaCluster') : t('clusters.registerHaCluster') }}</button><button class="btn role-primary btn-sm" :disabled="clusterStatusLoading" @click="openCluster(host)">{{ t('clusters.openCluster') }}</button></div></article></div>
          <div v-if="clusterStatusLoading" class="loading compact">{{ t('clusters.clusterLoading') }}</div>
          <div v-if="clusterStatusError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.clusterStatusError') }}</strong><p>{{ clusterStatusError }}</p></div>
          <template v-if="clusterStatus">
            <div class="cluster-detail-heading"><div><span class="eyebrow">{{ t('clusters.liveStatus') }}</span><h3>{{ clusterStatus.cluster_name || t('clusters.unnamedCluster') }}</h3><small>{{ t('clusters.statusSource', { host: clusterStatus.source_host_name }) }} · {{ dateLabel(clusterStatus.checked_at) }}</small></div><div class="cluster-heading-actions"><a v-if="clusterDiagnostics?.hawk_url" class="btn role-secondary btn-sm" :href="clusterDiagnostics.hawk_url" target="_blank" rel="noopener noreferrer">{{ t('clusters.openHawk') }}</a><button class="btn role-secondary btn-sm" :disabled="clusterStatusLoading" @click="fetchClusterStatus">{{ t('clusters.refresh') }}</button></div></div>
            <div class="cluster-detail-stats"><article><small>{{ t('clusters.nodes') }}</small><strong>{{ clusterStatus.online_count || 0 }} / {{ clusterStatus.node_count || 0 }}</strong><span>{{ t('clusters.onlineNodes') }}</span></article><article><small>{{ t('clusters.resources') }}</small><strong>{{ clusterStatus.resource_count || 0 }}</strong><span>{{ t('clusters.managedResources') }}</span></article><article><small>{{ t('clusters.quorum') }}</small><strong :class="clusterStatus.quorum?.quorate ? 'healthy-text' : 'warning-text'">{{ clusterStatus.quorum?.quorate ? t('clusters.quorate') : clusterStatus.quorum?.available ? t('clusters.notQuorate') : t('clusters.quorumUnknown') }}</strong><span>{{ quorumSummary }}</span></article><article><small>{{ t('clusters.fencing') }}</small><strong :class="clusterStatus.fencing?.configured ? 'healthy-text' : 'warning-text'">{{ clusterStatus.fencing?.configured ? t('clusters.fencingConfigured') : clusterStatus.fencing?.available ? t('clusters.fencingNotConfigured') : t('clusters.fencingUnknown') }}</strong><span>{{ fencingSummary }}</span></article></div>
            <div class="cluster-shortcuts"><button class="btn role-link" @click="activeSection = 'nodes'">{{ t('clusters.manageNodes') }}</button><button class="btn role-link" @click="activeSection = 'resources'">{{ t('clusters.manageResources') }}</button><button class="btn role-link" @click="activeSection = 'fencing'">{{ t('clusters.reviewQuorumFencing') }}</button></div>
          </template>
        </template>
        <p class="safety-note">{{ t('clusters.inventorySeparation') }}</p>
      </section>

      <section v-else-if="activeSection === 'nodes' || activeSection === 'resources'" :id="`cluster-panel-${activeSection}`" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t(`clusters.section_${activeSection}`) }}</h2><p>{{ t(`clusters.area_${activeSection}_description`) }}</p></div><div class="cluster-heading-actions"><button v-if="activeSection === 'resources' && canManageCluster && clusterStatus" class="btn role-secondary" @click="openCreateGroup">{{ t('clusters.createResourceGroup') }}</button><button v-if="activeSection === 'resources' && canManageCluster && clusterStatus" class="btn role-secondary" @click="openCreateClone">{{ t('clusters.createResourceClone') }}</button><button v-if="activeSection === 'resources' && canManageCluster && clusterStatus" class="btn role-primary" @click="openCreateResource">{{ t('clusters.createResource') }}</button><button class="btn role-secondary" :disabled="clusterStatusLoading || !activeClusterHostId" @click="fetchClusterStatus">{{ t('clusters.refresh') }}</button></div></div>
        <div v-if="!clusterStatus && !clusterStatusLoading" class="inline-callout info"><strong>{{ t('clusters.noLiveCluster') }}</strong><p>{{ clusterStatusError || t('clusters.noLiveClusterHelp') }}</p><button class="btn role-link" @click="activeSection = 'clusters'">{{ t('clusters.viewClusters') }}</button></div>
        <template v-else-if="clusterStatus">
          <div v-if="activeSection === 'nodes'" class="table-wrap"><table class="table"><thead><tr><th>{{ t('clusters.node') }}</th><th>{{ t('clusters.nodeStatus') }}</th><th>{{ t('clusters.standby') }}</th><th>{{ t('clusters.maintenance') }}</th><th>{{ t('clusters.operations') }}</th></tr></thead><tbody><tr v-for="node in clusterStatus.nodes" :key="node.id || node.name"><td><strong>{{ node.name }}</strong><small>{{ t('clusters.nodeId') }}: {{ node.id || '—' }}</small></td><td><span class="state" :class="node.online && !node.unclean ? 'ready' : 'unreachable'"><i></i>{{ node.online ? (node.unclean ? t('clusters.unclean') : t('clusters.online')) : t('clusters.offline') }}</span><small v-if="node.pending">{{ node.pending }}</small></td><td>{{ node.standby ? t('clusters.enabledState') : t('clusters.disabledState') }}</td><td>{{ node.maintenance ? t('clusters.enabledState') : t('clusters.disabledState') }}</td><td class="action-cell"><div class="cell-action-controls"><button v-if="!node.standby" class="btn role-secondary btn-sm" @click="requestClusterAction('node_standby', node.name)">{{ t('clusters.standbyNode') }}</button><button v-else class="btn role-secondary btn-sm" @click="requestClusterAction('node_online', node.name)">{{ t('clusters.bringOnline') }}</button><button v-if="!node.maintenance" class="btn role-secondary btn-sm" @click="requestClusterAction('node_maintenance', node.name)">{{ t('clusters.enterMaintenance') }}</button><button v-else class="btn role-secondary btn-sm" @click="requestClusterAction('node_ready', node.name)">{{ t('clusters.leaveMaintenance') }}</button></div></td></tr></tbody></table></div>
          <template v-else>
            <form v-if="cloneEditor" class="resource-editor" @submit.prevent="prepareCloneMutation">
              <div class="editor-heading"><div><span class="eyebrow">{{ t('clusters.resourceConfiguration') }}</span><h3>{{ cloneEditor.mode === 'edit' ? t('clusters.editCloneTitle', { id: cloneEditor.resource_id }) : t('clusters.createResourceClone') }}</h3><p>{{ cloneEditor.mode === 'edit' ? t('clusters.editCloneHelp') : t('clusters.createResourceCloneHelp') }}</p></div><button type="button" class="btn role-link btn-sm" @click="cloneEditor = null">{{ t('clusters.cancelAction') }}</button></div>
              <div class="resource-form-grid"><label>{{ t('clusters.cloneId') }}<input v-model.trim="cloneEditor.resource_id" required maxlength="128" pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" autocomplete="off" :readonly="cloneEditor.mode === 'edit'" /></label><label>{{ t('clusters.cloneType') }}<select v-if="cloneEditor.mode === 'create'" v-model="cloneEditor.clone_type"><option value="standard">{{ t('clusters.cloneStandard') }}</option><option value="promotable">{{ t('clusters.clonePromotable') }}</option></select><input v-else :value="t(cloneEditor.clone_type === 'promotable' ? 'clusters.clonePromotable' : 'clusters.cloneStandard')" readonly /></label><label>{{ t('clusters.cloneChildResource') }}<select v-if="cloneEditor.mode === 'create'" v-model="cloneEditor.child_id" required><option value="">{{ t('clusters.selectResource') }}</option><option v-for="resource in cloneableResources" :key="resource.id" :value="resource.id">{{ resource.id }} · {{ resource.agent }}</option></select><input v-else :value="cloneEditor.child_id" readonly /></label></div>
              <p v-if="cloneEditor.mode === 'create' && !cloneableResources.length" class="section-help">{{ t('clusters.noCloneableResources') }}</p>
              <p v-if="cloneEditor.mode === 'create' && cloneEditor.clone_type === 'promotable' && clusterStatus.resources.some((resource) => resource.id === cloneEditor.child_id && resource.agent === 'group')" class="section-help">{{ t('clusters.promotableCloneNeedsPrimitive') }}</p>
              <div v-if="cloneEditor.mode === 'create' && cloneEditor.clone_type === 'promotable' && cloneEditor.child_id && !promotableCloneMonitorsReady" class="inline-callout warning"><strong>{{ t('clusters.promotableMonitorTitle') }}</strong><p>{{ t('clusters.promotableCloneNeedsMonitors') }}</p><button type="button" class="btn role-secondary btn-sm" :disabled="!selectedClonePrimitive || selectedClonePrimitive.active" @click="selectedClonePrimitive && openMonitorEditor(selectedClonePrimitive)">{{ t('clusters.editMonitorOperations') }}</button></div>
              <section v-if="cloneEditor.mode === 'edit'" class="field-wide resource-parameters"><div class="resource-parameters-heading"><strong>{{ t('clusters.cloneOptions') }}</strong></div><p class="section-help">{{ t('clusters.cloneOptionsHelp') }}</p><div class="resource-form-grid clone-options-grid"><template v-for="field in cloneMetadataFields(cloneEditor.clone_type)" :key="field.key"><label v-if="field.kind === 'number'">{{ t(`clusters.cloneMeta_${field.key}`) }}<input :value="cloneEditor.metadata[field.key] || ''" type="number" min="1" max="4096" step="1" @input="setCloneMetadataInput(field.key, $event)" /></label><label v-else>{{ t(`clusters.cloneMeta_${field.key}`) }}<select v-model="cloneEditor.metadata[field.key]"><option value="">{{ t('clusters.cloneOptionDefault') }}</option><option value="true">{{ t('clusters.enabledState') }}</option><option value="false">{{ t('clusters.disabledState') }}</option></select></label></template></div><small class="section-help">{{ t('clusters.cloneOptionEmptyDefault') }}</small></section>
              <div class="inline-callout info"><strong>{{ t('clusters.cloneSafetyTitle') }}</strong><p>{{ cloneEditor.clone_type === 'promotable' ? t('clusters.clonePromotableHelp') : t('clusters.cloneStandardHelp') }}</p><p v-if="cloneEditor.mode === 'edit'">{{ t('clusters.cloneEditStoppedOnly') }}</p></div>
              <div v-if="resourceMutationError" class="inline-callout warning" role="alert">{{ resourceMutationError }}</div><div class="row-actions"><button type="button" class="btn role-secondary" @click="cloneEditor = null">{{ t('clusters.cancelAction') }}</button><button class="btn role-primary" :disabled="resourceMutationBusy || (cloneEditor.mode === 'create' && (!cloneableResources.length || !cloneEditor.resource_id || !cloneEditor.child_id || (cloneEditor.clone_type === 'promotable' && (clusterStatus.resources.some((resource) => resource.id === cloneEditor.child_id && resource.agent === 'group') || !promotableCloneMonitorsReady))))">{{ t(cloneEditor.mode === 'edit' ? 'clusters.reviewCloneEdit' : 'clusters.reviewCloneCreate') }}</button></div>
            </form>
            <form v-else-if="groupEditor" class="resource-editor" @submit.prevent="prepareGroupMutation">
              <div class="editor-heading"><div><span class="eyebrow">{{ t('clusters.resourceGroup') }}</span><h3>{{ groupEditor.mode === 'create' ? t('clusters.createResourceGroup') : t('clusters.editResourceGroup', { id: groupEditor.resource_id }) }}</h3><p>{{ t('clusters.resourceGroupHelp') }}</p></div><button type="button" class="btn role-link btn-sm" @click="groupEditor = null">{{ t('clusters.cancelAction') }}</button></div>
              <div class="inline-callout info"><strong>{{ t('clusters.groupOrderingTitle') }}</strong><p>{{ t('clusters.groupOrderingHelp') }}</p></div>
              <div v-if="groupEditor.mode === 'create'" class="resource-form-grid"><label>{{ t('clusters.resourceGroupId') }}<input v-model.trim="groupEditor.resource_id" required maxlength="128" pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" autocomplete="off" /></label><fieldset class="field-wide group-member-picker"><legend>{{ t('clusters.groupMembersOrder') }}</legend><label v-for="resource in groupableResources" :key="resource.id" class="group-member-option"><input type="checkbox" :checked="groupEditor.children.includes(resource.id)" :disabled="resource.active" @change="toggleGroupMember(resource.id, $event)" /><span><strong>{{ resource.id }}</strong><small>{{ resource.agent }} · {{ resource.active ? t('clusters.running') : t('clusters.stopped') }}</small></span></label><p v-if="!groupableResources.length" class="section-help">{{ t('clusters.noGroupableResources') }}</p></fieldset><ol v-if="groupEditor.children.length" class="field-wide group-order-list"><li v-for="(id, index) in groupEditor.children" :key="id"><span>{{ index + 1 }}. {{ id }}</span><div><button type="button" class="btn role-secondary btn-sm" :disabled="index === 0" :aria-label="t('clusters.moveGroupMemberUp', { resource: id })" @click="moveGroupMember(index, -1)">↑</button><button type="button" class="btn role-secondary btn-sm" :disabled="index === groupEditor.children.length - 1" :aria-label="t('clusters.moveGroupMemberDown', { resource: id })" @click="moveGroupMember(index, 1)">↓</button></div></li></ol></div>
