        <div class="table-wrap"><table class="table"><thead><tr><th>{{ t('clusters.resource') }}</th><th>{{ t('clusters.resourceType') }}</th><th>{{ t('clusters.resourceStatus') }}</th><th>{{ t('clusters.location') }}</th><th>{{ t('clusters.operations') }}</th></tr></thead><tbody><tr v-for="resource in clusterStatus.resources" :key="resource.id"><td><strong>{{ resource.id }}</strong><small v-if="resource.children?.length">{{ t('clusters.resourceMembersLabel', { members: resource.children.join(' → ') }) }}</small></td><td>{{ resource.agent || '—' }}</td><td><span class="state" :class="resource.failed ? 'unreachable' : resource.active ? 'ready' : 'warning-state'"><i></i>{{ resource.failed ? t('clusters.failed') : resource.active ? (resource.role || t('clusters.running')) : t('clusters.stopped') }}</span><small v-if="!resource.managed">{{ t('clusters.unmanaged') }}</small></td><td>{{ resource.nodes?.join(', ') || '—' }}</td><td class="action-cell"><div class="cell-action-controls"><button v-if="resource.active && !resource.parent_id && !resource.group_id" class="btn role-secondary btn-sm" @click="requestClusterAction('resource_stop', resource.id)">{{ t('clusters.stopResource') }}</button><button v-else-if="!resource.parent_id && !resource.group_id" class="btn role-secondary btn-sm" @click="requestClusterAction('resource_start', resource.id)">{{ t('clusters.startResource') }}</button><button v-if="resource.failed && !resource.parent_id && !resource.group_id" class="btn role-secondary btn-sm" @click="requestClusterAction('resource_cleanup', resource.id)">{{ t('clusters.cleanupResource') }}</button><template v-if="resource.agent === 'group'"><button v-if="canManageCluster && resource.managed && !resource.parent_id && !resource.active" class="btn role-link btn-sm" @click="openGroupEditor(resource)">{{ t('clusters.editGroupMembers') }}</button><button v-if="canManageCluster && resource.managed && !resource.parent_id && !resource.active" class="btn role-link btn-sm danger-text" @click="prepareGroupDelete(resource)">{{ t('clusters.deleteGroup') }}</button></template><template v-else-if="resource.agent === 'clone' || resource.agent === 'promotable clone'"><button v-if="canManageCluster && resource.managed && !resource.parent_id && !resource.active && !resource.failed && resource.clone_metadata_editable" class="btn role-link btn-sm" @click="openCloneEditor(resource)">{{ t('clusters.editCloneOptions') }}</button><button v-if="canManageCluster && validCloneDeletion(resource)" class="btn role-link btn-sm danger-text" @click="prepareCloneDelete(resource)">{{ t('clusters.deleteClone') }}</button></template><template v-else-if="resource.agent !== 'clone' && resource.agent !== 'promotable clone' && resource.class !== 'stonith' && !resource.agent?.startsWith('stonith:')"><button v-if="canManageCluster && resource.managed && !resource.parent_id && !resource.group_id && !resource.active" class="btn role-link btn-sm" :disabled="!canEditMonitorOperations(resource)" :title="!canEditMonitorOperations(resource) ? t('clusters.monitorOperationIdMissing') : ''" @click="openMonitorEditor(resource)">{{ t('clusters.editMonitorOperations') }}</button><button v-if="canManageCluster && resource.managed && !resource.parent_id && !resource.group_id" class="btn role-link btn-sm" @click="openResourceEditor(resource)">{{ t('clusters.editResource') }}</button><button v-if="canManageCluster && resource.managed && !resource.parent_id && !resource.group_id" class="btn role-link btn-sm danger-text" @click="prepareResourceDelete(resource)">{{ t('clusters.deleteResource') }}</button></template></div></td></tr><tr v-if="!clusterStatus.resources?.length"><td colspan="5" class="empty-row">{{ t('clusters.noResources') }}</td></tr></tbody></table></div>
