{{ t('clusters.fencingSbdScopeHelp') }}</p></article></div><div v-else class="inline-callout info"><strong>{{ t('clusters.noLiveCluster') }}</strong><p>{{ clusterStatusError || t('clusters.noLiveClusterHelp') }}</p></div>
