ers.showFencingSecret') }}</button><button v-if="!parameter.existing" type="button" class="btn role-link btn-sm" :aria-label="t('clusters.removeResourceParameter', { number: index + 1 })" @click="fencingEditor.parameters.splice(index, 1)">{{ t('clusters.removeResourceParameterShort') }}</button></div></section>
