ton></div><small v-if="device.stonith_status_check" class="fencing-status-result">{{ t(`clusters.fencingStatus_${device.stonith_status_check.status}`) }} · {{ fencingCheckTime(device.stonith_status_check.checked_at) }}</small><small v-if="fencingCheckCooldownActive(device)" class="fencing-status-result">{{ t('clusters.fencingStatusNextCheck', { time: fencingCheckTime(device.stonith_status_check?.next_allowed_at || '') }) }}</small><small v-if="fencingDeviceCheckErrors[device.id]" class="fencing-status-error" role="alert">{{ fencingDeviceCheckErrors[device.id] }}</small></td></tr></tbody></table></div><div v-else><p class="empty-row">{{ t('clusters.noFencingDevices') }}</p><div v-if="clusterStatus.fencing?.sbd?.configured" class="inline-callout info"><strong>{{ t('clusters.fencingSbdNoResourceTitle') }}</strong><p>{{ t('clusters.fencingSbdNoResourceHelp') }}</p></div></div></section>
