          <div v-if="clusterDiagnosticsError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.diagnosticsError') }}</strong><p>{{ clusterDiagnosticsError }}</p></div>
          <article v-if="clusterDiagnostics?.locking_topology" class="diagnostic-card"><h3>{{ t('clusters.vmLockTopologyTitle') }}</h3><p class="section-help">{{ t('clusters.vmLockTopologyHelp') }}</p><div v-if="!clusterDiagnostics.locking_topology.available" class="inline-callout warning"><strong>{{ t('clusters.vmLockTopologyUnavailable') }}</strong><p>{{ clusterDiagnostics.locking_topology.error || t('clusters.diagnosticsUnavailable') }}</p></div><template v-else><div class="vm-resource-facts-grid"><span><small>{{ t('clusters.vmLockDlmResources') }}</small><strong>{{ clusterDiagnostics.locking_topology.dlm_resources?.join(', ') || t('clusters.vmResourceNotConfigured') }}</strong></span><span><small>{{ t('clusters.vmLockGfs2Resources') }}</small><strong>{{ clusterDiagnostics.locking_topology.gfs2_resources?.map((resource) => resource.id).join(', ') || t('clusters.vmResourceNotConfigured') }}</strong></span><span><small>{{ t('clusters.vmLockGroup') }}</small><strong>{{ clusterDiagnostics.locking_topology.lock_group_ids?.join(', ') || t('clusters.vmResourceNotConfigured') }}</strong></span><span><small>{{ t('clusters.vmLockClone') }}</small><strong>{{ clusterDiagnostics.locking_topology.lock_clone_ids?.join(', ') || t('clusters.vmResourceNotConfigured') }}</strong></span><span><small>{{ t('clusters.vmLockspaceDirectory') }}</small><strong>{{ clusterDiagnostics.locking_topology.lockspace_directory || t('clusters.vmResourceNotConfigured') }}</strong> · {{ t(clusterDiagnostics.locking_topology.lockspace_matches_gfs2 ? 'clusters.vmLockspaceOnGfs2' : clusterDiagnostics.locking_topology.lockspace_matches_gfs2 === false ? 'clusters.vmLockspaceNotOnGfs2' : 'clusters.vmResourceUnknown') }}</span><span><small>{{ t('clusters.vmLockRuntimeStatus') }}</small><strong>{{ t(clusterDiagnostics.locking_topology.runtime_active_on_all_online_nodes === true ? 'clusters.vmLockRuntimeAll' : clusterDiagnostics.locking_topology.runtime_active_on_all_online_nodes === false ? 'clusters.vmLockRuntimePartial' : 'clusters.vmLockRuntimeUnknown') }}</strong><small v-if="clusterDiagnostics.locking_topology.runtime_available">{{ t('clusters.vmLockRuntimeNodes', { active: clusterDiagnostics.locking_topology.runtime_active_nodes?.join(', ') || '—', online: clusterDiagnostics.locking_topology.runtime_online_nodes?.join(', ') || '—' }) }}</small></span></div><div :class="clusterDiagnostics.locking_topology.complete ? 'inline-callout success' : clusterDiagnostics.locking_topology.lock_stack_detected ? 'inline-callout info' : 'inline-callout warning'"><strong>{{ t(clusterDiagnostics.locking_topology.complete ? 'clusters.vmLockTopologyDetected' : clusterDiagnostics.locking_topology.lock_stack_detected ? 'clusters.vmLockStackReadyNoVm' : 'clusters.vmLockTopologyIncomplete') }}</strong><p>{{ t('clusters.vmLockTopologyScope') }}</p></div><ul v-if="clusterDiagnostics.locking_topology.vm_resources?.length"><li v-for="vm in clusterDiagnostics.locking_topology.vm_resources" :key="vm"><strong>{{ vm }}</strong> · {{ t(clusterDiagnostics.locking_topology.vm_constraints?.[vm]?.ordered_after_lock ? 'clusters.vmLockOrdered' : 'clusters.vmLockOrderMissing') }} · {{ t(clusterDiagnostics.locking_topology.vm_constraints?.[vm]?.colocated_with_lock ? 'clusters.vmLockColocated' : 'clusters.vmLockColocationMissing') }}</li></ul><p v-else class="empty-row">{{ t('clusters.vmLockNoVmResources') }}</p></template></article>
          <div v-if="constraintEditor" class="resource-editor"><div class="editor-heading"><div><span class="eyebrow">{{ t('clusters.constraintConfiguration') }}</span><h3>{{ t(`clusters.${constraintEditor.action}`) }}</h3><p>{{ t('clusters.constraintEditorHelp') }}</p></div><button type="button" class="btn role-link btn-sm" @click="constraintEditor = null">{{ t('clusters.cancelAction') }}</button></div><div class="resource-form-grid"><label>{{ t('clusters.constraintId') }}<input v-model.trim="constraintEditor.constraint_id" required maxlength="128" pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" autocomplete="off" /></label><label>{{ t('clusters.constraintType') }}<select :value="constraintEditor.action" @change="changeConstraintType($event)"><option value="create_location">{{ t('clusters.constraint_location') }}</option><option value="create_order">{{ t('clusters.constraint_ordering') }}</option><option value="create_colocation">{{ t('clusters.constraint_colocation') }}</option></select></label><label>{{ t('clusters.resource') }}<select v-model="constraintEditor.resource" required><option value="">{{ t('clusters.selectResource') }}</option><option v-for="resource in clusterStatus?.resources || []" :key="resource.id" :value="resource.id">{{ resource.id }}</option></select></label><label v-if="constraintEditor.action !== 'create_location'">{{ t('clusters.otherResource') }}<select v-model="constraintEditor.other_resource" required><option value="">{{ t('clusters.selectResource') }}</option><option v-for="resource in clusterStatus?.resources || []" :key="resource.id" :value="resource.id">{{ resource.id }}</option></select></label><label v-if="constraintEditor.action === 'create_location'">{{ t('clusters.clusterNode') }}<select v-model="constraintEditor.node" required><option value="">{{ t('clusters.selectNode') }}</option><option v-for="node in clusterStatus?.nodes || []" :key="node.id || node.name" :value="node.name">{{ node.name }}</option></select></label><label v-if="constraintEditor.action === 'create_location' || constraintEditor.action === 'create_colocation'">{{ t('clusters.constraintScore') }}<input v-model.trim="constraintEditor.score" required maxlength="16" placeholder="INFINITY, -INFINITY, 100" /></label><label v-if="constraintEditor.action === 'create_order'">{{ t('clusters.orderKind') }}<select v-model="constraintEditor.order_kind"><option value="Mandatory">{{ t('clusters.orderMandatory') }}</option><option value="Optional">{{ t('clusters.orderOptional') }}</option><option value="Serialize">{{ t('clusters.orderSerialize') }}</option></select></label></div><div class="row-actions"><button type="button" class="btn role-secondary" @click="constraintEditor = null">{{ t('clusters.cancelAction') }}</button><button type="button" class="btn role-primary" :disabled="!constraintEditor.constraint_id || !constraintEditor.resource" @click="prepareConstraintMutation">{{ t('clusters.reviewConstraint') }}</button></div></div>
          <div v-if="constraintMutationError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.constraintMutationFailed') }}</strong><p>{{ constraintMutationError }}</p></div><div v-if="constraintMutationMessage" class="inline-callout success" role="status"><strong>{{ t('clusters.constraintMutationSucceeded') }}</strong><p>{{ constraintMutationMessage }}</p></div>
          <div v-if="pendingConstraintMutation" class="inline-callout warning action-review"><strong>{{ t('clusters.reviewConstraintTitle') }}</strong><p>{{ constraintMutationSummary }}</p><small>{{ t('clusters.constraintChangeSafety') }}</small><div><button class="btn role-primary btn-sm" :disabled="constraintMutationBusy" @click="runConstraintMutation">{{ constraintMutationBusy ? t('clusters.constraintChangeRunning') : t('clusters.confirmAction') }}</button><button class="btn role-secondary btn-sm" :disabled="constraintMutationBusy" @click="pendingConstraintMutation = null">{{ t('clusters.cancelAction') }}</button></div></div>
          <div class="constraint-groups"><article v-for="kind in ['location','ordering','colocation']" :key="kind" class="diagnostic-card"><h3>{{ t(`clusters.constraint_${kind}`) }}</h3><ul v-if="clusterDiagnostics.constraints?.[kind]?.items?.length"><li v-for="item in clusterDiagnostics.constraints[kind].items" :key="item"><span>{{ item }}</span><button v-if="canManageCluster" class="btn role-link btn-sm danger-text" :aria-label="t('clusters.deleteConstraint', { id: constraintId(item) })" @click="prepareConstraintDelete(item)">{{ t('clusters.deleteConstraintShort') }}</button></li></ul><p v-else>{{ clusterDiagnostics.constraints?.[kind]?.error || t('clusters.noConstraints') }}</p></article></div>
          <small class="data-stamp">{{ t('clusters.diagnosticsCheckedAt') }}: {{ dateLabel(clusterDiagnostics.checked_at) }}</small>
        </template>
      </section>

      <section v-else-if="activeSection === 'activity'" id="cluster-panel-activity" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.clusterAdministration') }}</span><h2>{{ t('clusters.section_activity') }}</h2><p>{{ t('clusters.area_activity_description') }}</p></div><button class="btn role-secondary" :disabled="diagnosticsLoading || !activeClusterHostId" @click="fetchClusterDiagnostics">{{ diagnosticsLoading ? t('clusters.diagnosticsLoading') : t('clusters.refresh') }}</button></div>
        <div v-if="!activeClusterHostId" class="inline-callout info"><strong>{{ t('clusters.noLiveCluster') }}</strong><p>{{ t('clusters.selectClusterForDetails') }}</p><button class="btn role-link" @click="activeSection = 'clusters'">{{ t('clusters.viewClusters') }}</button></div>
        <div v-else-if="diagnosticsLoading" class="loading compact">{{ t('clusters.diagnosticsLoading') }}</div>
        <template v-else-if="clusterDiagnostics || clusterDiagnosticsError"><div v-if="clusterDiagnosticsError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.diagnosticsError') }}</strong><p>{{ clusterDiagnosticsError }}</p></div><article v-if="clusterDiagnostics" class="diagnostic-card"><h3>{{ t('clusters.recentServiceEvents') }}</h3><pre v-if="clusterDiagnostics.activity?.available && clusterDiagnostics.activity.summary">{{ clusterDiagnostics.activity.summary }}</pre><p v-else>{{ clusterDiagnostics.activity?.error || t('clusters.noActivity') }}</p></article><small v-if="clusterDiagnostics" class="data-stamp">{{ t('clusters.diagnosticsWindow') }} · {{ dateLabel(clusterDiagnostics.checked_at) }}</small></template>
      </section>

      <section v-else-if="activeSection === 'overview'" id="cluster-panel-overview" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.readiness') }}</span><h2>{{ t('clusters.hostsTitle') }}</h2><p>{{ t('clusters.hostsDescription') }}</p></div><button class="btn role-primary" @click="goToHosts">{{ t('clusters.manageHosts') }}</button></div>
        <div v-if="!hosts.length" class="empty-state"><h3>{{ t('clusters.noHosts') }}</h3><p>{{ t('clusters.noHostsHelp') }}</p><button class="btn role-primary" @click="goToHosts">{{ t('clusters.addHost') }}</button></div>
        <div v-else class="table-wrap"><table class="table"><thead><tr><th>{{ t('clusters.host') }}</th><th>{{ t('clusters.hostState') }}</th><th>{{ t('clusters.haAddon') }}</th><th>{{ t('clusters.clusterStack') }}</th><th>{{ t('clusters.clusterState') }}</th><th>{{ t('clusters.resources') }}</th><th>{{ t('clusters.checkedAt') }}</th><th></th></tr></thead>
          <tbody><tr v-for="host in hosts" :key="host.id">
            <td><strong>{{ host.hostname || host.name }}</strong><small>{{ host.address }}:{{ host.port }}</small></td>
            <td><span class="state" :class="host.status"><i></i>{{ statusLabel(host.status) }}</span><small v-if="host.last_error">{{ host.last_error }}</small></td>
            <td><span class="state" :class="haClass(host)"><i></i>{{ haLabel(host) }}</span><small v-if="host.ha?.ha_product">{{ host.ha.ha_product }}</small><small v-else-if="host.ha?.inspection_error">{{ host.ha.inspection_error }}</small><small v-else-if="host.ha?.extension_error">{{ host.ha.extension_error }}</small></td>
            <td><div class="stack-status"><span :class="serviceClass(host,'pacemaker')">{{ t('clusters.pacemaker') }}: {{ serviceLabel(host,'pacemaker') }}</span><span :class="serviceClass(host,'corosync')">{{ t('clusters.corosync') }}: {{ serviceLabel(host,'corosync') }}</span><span :class="serviceClass(host,'hawk')">{{ t('clusters.hawk') }}: {{ serviceLabel(host,'hawk') }}</span><span :class="serviceClass(host,'hawk-backend')">{{ t('clusters.hawkBackend') }}: {{ serviceLabel(host,'hawk-backend') }}</span></div></td>
            <td><span class="state" :class="clusterStateClass(host)"><i></i>{{ t(clusterStateKey(host)) }}</span><small v-if="host.ha?.cluster_summary" class="cluster-summary">{{ host.ha.cluster_summary }}</small></td>
            <td>{{ host.cpu_count ? `${host.cpu_count} vCPU` : '—' }}<small>{{ memoryLabel(host.memory_total_bytes) }}</small></td>
            <td>{{ dateLabel(host.ha?.checked_at || host.last_checked_at) }}</td>
            <td class="action-cell"><div class="cell-action-controls"><button class="btn role-link btn-sm" @click="goToSubscriptions(host)">{{ t('clusters.manageSubscription') }}</button><span v-if="host.ha?.ha_active && haToolsInstalled(host)" class="state ready ha-tools-state"><i></i>{{ t('clusters.haToolsInstalled') }}</span><button v-else-if="host.ha?.ha_active" class="btn role-secondary btn-sm" :disabled="!canManageCluster || haToolBusyHostIds.includes(host.id)" :title="!canManageCluster ? t('clusters.operatorRoleRequired') : ''" @click="installHaTools(host)">{{ haToolBusyHostIds.includes(host.id) ? t('clusters.haToolsInstalling') : t('clusters.enableHaTools') }}</button><small v-if="!host.ha?.ha_active && host.ha?.ha_available">{{ t('clusters.activateHaAddonFirst') }}</small><div v-if="haToolResults[host.id]" class="ha-tool-result" :class="haToolResults[host.id].status"><span>{{ haToolResults[host.id].message || haToolResults[host.id].error }}</span><small v-if="haToolResults[host.id].status === 'installed'">{{ t('clusters.serviceActivationGuide') }}</small></div></div></td>
          </tr></tbody>
        </table></div>
        <p class="safety-note">{{ t('clusters.readOnlyNote') }}</p>
      </section>

      <section v-else-if="activeSection === 'templates'" id="cluster-panel-templates" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.templateCatalog') }}</span><h2>{{ t('clusters.templatesTitle') }}</h2><p>{{ t('clusters.templatesDescription') }}</p></div><button class="btn role-secondary" :disabled="preflightLoading || templateHostIds.length < 2" @click="runPreflight(templateHostIds)">{{ preflightLoading ? t('clusters.preflightRunning') : t('clusters.validateTemplates') }}</button></div>
        <div class="inline-callout info"><strong>{{ t('clusters.templatesUseExisting') }}</strong><p>{{ t('clusters.templatesUseExistingHelp') }}</p></div>
        <section class="template-host-selection" aria-labelledby="template-host-selection-title"><h3 id="template-host-selection-title">{{ t('clusters.templateSelectHosts') }}</h3><p class="section-help">{{ t('clusters.templateSelectHostsHelp') }}</p><div v-if="!templateCandidateHosts.length" class="inline-callout warning"><strong>{{ t('clusters.noEligibleHosts') }}</strong><p>{{ t('clusters.templateNoHostsHelp') }}</p></div><div v-else class="host-picker"><label v-for="host in templateCandidateHosts" :key="`template-${host.id}`" class="host-option"><input v-model="templateHostIds" type="checkbox" :value="host.id"><span><strong>{{ host.hostname || host.name }}</strong><small>{{ host.address }} · {{ haLabel(host) }}</small></span><span class="state" :class="templateHostIds.includes(host.id) ? 'ready' : 'unknown'"><i></i>{{ templateHostIds.includes(host.id) ? t('clusters.selected') : t('clusters.notSelected') }}</span></label></div><div v-if="templateHostIds.length < 2" class="inline-callout info"><strong>{{ t('clusters.selectAtLeastTwo') }}</strong><p>{{ t('clusters.templateNeedsTwoHosts') }}</p></div><div v-if="preflightError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.preflightError') }}</strong><p>{{ preflightError }}</p></div><small v-if="preflightResults.length" class="template-check-stamp">{{ t('clusters.templateCheckedAt', { time: dateLabel(preflightResults[0]?.checked_at) }) }}</small><div v-if="preflightResults.length === templateHostIds.length && templateHostIds.length >= 2" class="inline-callout info shared-network-candidates"><strong>{{ t('clusters.sharedNetworkCandidatesTitle') }}</strong><p>{{ sharedTemplateNetworkCandidates.length ? t('clusters.sharedNetworkCandidatesHelp') : t('clusters.noSharedNetworkCandidates') }}</p><ul v-if="sharedTemplateNetworkCandidates.length"><li v-for="candidate in sharedTemplateNetworkCandidates" :key="candidate.subnet"><code>{{ candidate.subnet }}</code><span v-for="host in candidate.hosts" :key="host.hostName"> · {{ host.hostName }}: {{ host.interfaces.join(', ') || t('clusters.interfaceUnknown') }}</span></li></ul><p class="section-help">{{ t('clusters.sharedNetworkCandidatesCaveat') }}</p></div></section>
        <div class="template-grid" aria-live="polite">
          <article v-for="templateId in clusterTemplateIds" :key="templateId" class="cluster-template-card">
            <div class="template-card-heading"><div><span class="eyebrow">{{ t(`clusters.template_${templateId}_category`) }}</span><h3>{{ t(`clusters.template_${templateId}_title`) }}</h3></div><span class="state" :class="templateEvaluation(templateId).tone"><i></i>{{ t(`clusters.template_fit_${templateEvaluation(templateId).fit}`) }}</span></div>
            <p>{{ t(`clusters.template_${templateId}_description`) }}</p>
            <div v-if="templateId === 'nfs'" class="template-storage-choice"><label for="nfs-storage-mode">{{ t('clusters.templateNfsStorageMode') }}</label><select id="nfs-storage-mode" v-model="nfsStorageMode"><option value="drbd">{{ t('clusters.templateNfsStorageDrbd') }}</option><option value="shared">{{ t('clusters.templateNfsStorageShared') }}</option></select><small>{{ t(`clusters.templateNfsStorageModeHelp_${nfsStorageMode}`) }}</small></div>
            <div class="template-card-summary"><span>{{ templateRequirementSummary(templateId) }}</span><span v-if="templateId === 'vm' && selectedTemplateHosts.length >= 2">{{ templateMinimumCapacity() }}</span></div>
            <div v-if="templateRemediation(templateId)" class="template-blocker"><span>{{ templateRemediationText(templateId) }}</span><button class="btn role-link btn-sm" :disabled="templateRemediationDisabled(templateId)" @click="runTemplateRemediation(templateId)">{{ templateRemediationLoading(templateId) ? t('clusters.templateResolving') : templateRemediationLabel(templateId) }}</button></div>
            <div v-if="templateHostIds.length >= 2 && !preflightResults.length" class="template-fix-empty"><span><strong>{{ t('clusters.templateFixesNeedCheck') }}</strong><small>{{ t('clusters.templateFixesNeedCheckHelp') }}</small></span><button class="btn role-secondary btn-sm" :disabled="preflightLoading" @click="runPreflight(templateHostIds)">{{ preflightLoading ? t('clusters.preflightRunning') : t('clusters.validateTemplates') }}</button></div>
            <section v-if="templateActionableRequirements(templateId).length" class="template-remediation-list" :aria-label="t('clusters.templateResolveRequirements')"><div class="template-remediation-heading"><strong>{{ t('clusters.templateFixesTitle') }}</strong><small>{{ t('clusters.templateFixesHelp') }}</small></div><div v-for="requirement in templateActionableRequirements(templateId)" :key="requirement.key" class="template-remediation-row"><span><strong>{{ requirement.text }}</strong><small>{{ templateRequirementHelp(templateId, requirement.key) }}</small></span><button class="btn role-secondary btn-sm" :aria-label="templateRequirementActionAriaLabel(templateId, requirement)" :title="!canManageCluster && templateRequirementActionDisabled(templateId, requirement.key) ? t('clusters.operatorRoleRequired') : ''" :disabled="templateRequirementActionDisabled(templateId, requirement.key)" @click="runTemplateRequirementAction(templateId, requirement.key)">{{ templateRequirementActionLabel(templateId, requirement.key) }}</button></div></section>
            <div v-if="templateHostActionResults(templateId).length" class="template-action-results" role="status" aria-live="polite"><p v-for="result in templateHostActionResults(templateId)" :key="result.host_id"><strong>{{ result.host_name }}:</strong> {{ result.message || result.error || operationStatusText(result.status) }}</p></div>
            <div v-if="templateResolveError && templateActionTemplateId === templateId" class="inline-callout warning template-resolve-error" role="alert">{{ templateResolveError }}</div>
            <details class="template-details"><summary>{{ t('clusters.templateRequirements') }} · {{ t('clusters.templateConfigurationPreview') }}</summary>
              <ul class="template-requirement-list"><li v-for="requirement in templateEvaluation(templateId).requirements" :key="requirement.key" :class="requirement.ok === null ? 'check-warning' : requirement.ok ? 'check-ok' : 'check-blocked'"><span>{{ requirement.text }}</span><small>{{ requirement.ok === null ? t('clusters.templateStatusPending') : requirement.ok ? t('clusters.templateStatusMet') : t('clusters.templateStatusMissing') }}</small></li></ul>
              <ul class="template-resource-flow"><li v-for="item in templatePreviewItems(templateId)" :key="item">{{ item }}</li></ul>
              <p class="template-manual-summary"><strong>{{ t('clusters.templateManualChecks') }}:</strong> {{ templateEvaluation(templateId).manual.join(' · ') }}</p>
            </details>
            <details v-if="templateEvaluation(templateId).hostChecks.length" class="template-details"><summary>{{ t('clusters.templateHostBreakdown') }}</summary><article v-for="hostCheck in templateEvaluation(templateId).hostChecks" :key="hostCheck.name" class="template-host-row"><div><strong>{{ hostCheck.name }}</strong><span class="state" :class="hostCheck.ok ? 'ready' : hostCheck.reviewRequired ? 'warning-state' : 'unreachable'"><i></i>{{ t(hostCheck.ok ? 'clusters.templateStatusMet' : hostCheck.reviewRequired ? 'clusters.templateStatusPending' : 'clusters.templateStatusMissing') }}</span></div><ul><li v-for="item in hostCheck.evidence" :key="item">{{ item }}</li></ul><p v-if="hostCheck.nextSteps.length" class="template-next-step">{{ hostCheck.nextSteps.join(' · ') }}</p></article></details>
            <div class="template-card-footer"><button v-if="activeClusterHostId && clusterStatus" class="btn role-secondary btn-sm" :disabled="!canManageCluster || resourceMutationBusy || nfsServiceBusy || serviceVipBusy" :title="!canManageCluster ? t('clusters.operatorRoleRequired') : ''" @click="configureTemplateResource(templateId)">{{ t(templateId === 'nfs' ? 'clusters.nfsConfigureService' : templateId === 'service' ? 'clusters.serviceVipConfigure' : templateId === 'web' ? 'clusters.apacheConfigureService' : 'clusters.templatePrepareResource') }}</button><button class="btn role-primary btn-sm" :disabled="templateEvaluation(templateId).fit !== 'candidate'" @click="useTemplate(templateId)">{{ t('clusters.useTemplate') }}</button></div>
          </article>
        </div>
        <form v-if="nfsServiceDraft" class="resource-editor nfs-service-wizard" @submit.prevent="prepareNfsService">
          <div class="editor-heading"><div><span class="eyebrow">{{ t('clusters.nfsWizardEyebrow') }}</span><h3>{{ t('clusters.nfsWizardTitle') }}</h3><p>{{ t('clusters.nfsWizardHelp') }}</p></div><button type="button" class="btn role-link btn-sm" @click="closeNfsServiceWizard">{{ t('clusters.cancelAction') }}</button></div>
          <div class="inline-callout warning"><strong>{{ t('clusters.nfsWizardSafetyTitle') }}</strong><p>{{ t('clusters.nfsWizardSafetyHelp') }}</p></div>
          <div class="resource-form-grid">
            <label>{{ t('clusters.nfsResourcePrefix') }}<input v-model.trim="nfsServiceDraft.resource_prefix" required maxlength="48" pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" autocomplete="off" /></label>
            <label>{{ t('clusters.templateNfsStorageMode') }}<select v-model="nfsServiceDraft.storage_mode"><option value="drbd">{{ t('clusters.templateNfsStorageDrbd') }}</option><option value="shared">{{ t('clusters.templateNfsStorageShared') }}</option></select></label>
            <label v-if="nfsServiceDraft.storage_mode === 'drbd'">{{ t('clusters.nfsDrbdResource') }}<input v-model.trim="nfsServiceDraft.drbd_resource" required maxlength="64" pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" /></label>
            <label>{{ t('clusters.nfsStateDevice') }}<input v-model.trim="nfsServiceDraft.state_device" required maxlength="255" placeholder="/dev/drbd0" /></label>
            <label>{{ t('clusters.nfsDataDevice') }}<input v-model.trim="nfsServiceDraft.data_device" required maxlength="255" placeholder="/dev/drbd1" /></label>
            <label>{{ t('clusters.nfsExportDirectory') }}<input v-model.trim="nfsServiceDraft.share_directory" required maxlength="255" placeholder="/srv/nfs/share" /></label>
            <label>{{ t('clusters.nfsFilesystem') }}<select v-model="nfsServiceDraft.filesystem"><option value="ext4">ext4</option><option value="xfs">XFS</option></select></label>
            <label>{{ t('clusters.nfsClientspec') }}<input v-model.trim="nfsServiceDraft.clientspec" required maxlength="64" placeholder="192.0.2.0/24" /></label>
            <label>{{ t('clusters.nfsVirtualIp') }}<input v-model.trim="nfsServiceDraft.virtual_ip" required maxlength="64" placeholder="192.0.2.50" /></label>
            <label>{{ t('clusters.nfsCidrNetmask') }}<input v-model.number="nfsServiceDraft.cidr_netmask" required type="number" min="1" max="128" /></label>
          </div>
          <label v-if="nfsServiceDraft.storage_mode === 'shared'" class="nfs-shared-confirm"><input v-model="nfsServiceDraft.shared_storage_confirmed" type="checkbox" required /><span>{{ t('clusters.nfsSharedStorageConfirm') }}</span></label>
          <div class="inline-callout info"><strong>{{ t('clusters.nfsWizardPrerequisitesTitle') }}</strong><p>{{ t('clusters.nfsWizardPrerequisitesHelp') }}</p><ul><li>{{ t('clusters.nfsWizardQuorum', { state: clusterStatus?.quorum?.quorate ? t('clusters.quorate') : t('clusters.notQuorate') }) }}</li><li>{{ t('clusters.nfsWizardFencing', { state: clusterStatus?.fencing?.configured ? t('clusters.fencingConfigured') : t('clusters.fencingNotConfigured') }) }}</li><li>{{ t('clusters.nfsWizardAgentsChecked') }}</li></ul></div>
          <div v-if="nfsServiceError" class="inline-callout warning" role="alert">{{ nfsServiceError }}</div>
          <div v-if="nfsServiceReview" class="inline-callout warning action-review"><strong>{{ t('clusters.nfsReviewTitle') }}</strong><p>{{ nfsServiceSummary }}</p><small>{{ t('clusters.nfsReviewSafety') }}</small><div class="row-actions"><button type="button" class="btn role-secondary" :disabled="nfsServiceBusy" @click="nfsServiceReview = false">{{ t('clusters.editResource') }}</button><button type="button" class="btn role-primary" :disabled="nfsServiceBusy || !nfsServiceReady" @click="createNfsService">{{ nfsServiceBusy ? t('clusters.nfsCreating') : t('clusters.nfsCreateStopped') }}</button></div></div>
          <div v-else class="row-actions"><button type="button" class="btn role-secondary" @click="closeNfsServiceWizard">{{ t('clusters.cancelAction') }}</button><button class="btn role-primary" :disabled="!nfsServiceReady">{{ t('clusters.nfsReviewTitle') }}</button></div>
        </form>
        <div v-if="nfsServiceResult" class="inline-callout success" role="status"><strong>{{ t('clusters.nfsCreatedTitle') }}</strong><p>{{ nfsServiceResult.message }}</p></div>
        <form v-if="serviceVipDraft" class="resource-editor service-vip-wizard" @submit.prevent="prepareServiceVip">
          <div class="editor-heading"><div><span class="eyebrow">{{ t('clusters.serviceVipEyebrow') }}</span><h3>{{ t(serviceVipDraft.profile === 'apache' ? 'clusters.apacheWizardTitle' : 'clusters.serviceVipTitle') }}</h3><p>{{ t(serviceVipDraft.profile === 'apache' ? 'clusters.apacheWizardHelp' : 'clusters.serviceVipHelp') }}</p></div><button type="button" class="btn role-link btn-sm" @click="closeServiceVipWizard">{{ t('clusters.cancelAction') }}</button></div>
          <div class="inline-callout warning"><strong>{{ t(serviceVipDraft.profile === 'apache' ? 'clusters.apacheSafetyTitle' : 'clusters.serviceVipSafetyTitle') }}</strong><p>{{ t(serviceVipDraft.profile === 'apache' ? 'clusters.apacheSafetyHelp' : 'clusters.serviceVipSafetyHelp') }}</p></div>
          <div class="resource-form-grid"><label>{{ t('clusters.nfsResourcePrefix') }}<input v-model.trim="serviceVipDraft.resource_prefix" required maxlength="48" pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" autocomplete="off" /></label><label>{{ t('clusters.serviceVipUnit') }}<input v-model.trim="serviceVipDraft.service_unit" required maxlength="128" pattern="[A-Za-z0-9][A-Za-z0-9_.@:-]{0,120}\.service" placeholder="apache2.service" autocomplete="off" /></label><label v-if="serviceVipDraft.profile === 'apache'">{{ t('clusters.apacheConfigfile') }}<input v-model.trim="serviceVipDraft.apache_configfile" required maxlength="255" placeholder="/etc/apache2/httpd.conf" autocomplete="off" /></label><label>{{ t('clusters.nfsVirtualIp') }}<input v-model.trim="serviceVipDraft.virtual_ip" required maxlength="64" placeholder="192.0.2.50" /></label><label>{{ t('clusters.nfsCidrNetmask') }}<input v-model.number="serviceVipDraft.cidr_netmask" required type="number" min="1" max="128" /></label></div>
          <label class="nfs-shared-confirm"><input v-model="serviceVipDraft.shared_network_confirmed" type="checkbox" required /><span>{{ t('clusters.serviceVipNetworkConfirm') }}</span></label>
          <label v-if="serviceVipDraft.profile === 'apache'" class="nfs-shared-confirm"><input v-model="serviceVipDraft.apache_start_order_confirmed" type="checkbox" required /><span>{{ t('clusters.apacheStartOrderConfirm') }}</span></label>
          <div class="inline-callout info"><strong>{{ t('clusters.nfsWizardPrerequisitesTitle') }}</strong><p>{{ t(serviceVipDraft.profile === 'apache' ? 'clusters.apachePrerequisitesHelp' : 'clusters.serviceVipPrerequisitesHelp') }}</p><ul><li>{{ t('clusters.nfsWizardQuorum', { state: clusterStatus?.quorum?.quorate ? t('clusters.quorate') : t('clusters.notQuorate') }) }}</li><li>{{ t('clusters.nfsWizardFencing', { state: clusterStatus?.fencing?.configured ? t('clusters.fencingConfigured') : t('clusters.fencingNotConfigured') }) }}</li><li>{{ t('clusters.serviceVipAllNodesCheck') }}</li></ul></div>
          <div v-if="serviceVipError" class="inline-callout warning" role="alert">{{ serviceVipError }}</div>
          <div v-if="serviceVipReview" class="inline-callout warning action-review"><strong>{{ t(serviceVipDraft.profile === 'apache' ? 'clusters.apacheReviewTitle' : 'clusters.serviceVipReviewTitle') }}</strong><p>{{ serviceVipSummary }}</p><small>{{ t(serviceVipDraft.profile === 'apache' ? 'clusters.apacheReviewSafety' : 'clusters.serviceVipReviewSafety') }}</small><div class="row-actions"><button type="button" class="btn role-secondary" :disabled="serviceVipBusy" @click="serviceVipReview = false">{{ t('clusters.editResource') }}</button><button type="button" class="btn role-primary" :disabled="serviceVipBusy || !serviceVipReady" @click="createServiceVip">{{ serviceVipBusy ? t('clusters.serviceVipCreating') : t('clusters.serviceVipCreateStopped') }}</button></div></div>
          <div v-else class="row-actions"><button type="button" class="btn role-secondary" @click="closeServiceVipWizard">{{ t('clusters.cancelAction') }}</button><button class="btn role-primary" :disabled="!serviceVipReady">{{ t('clusters.serviceVipReviewTitle') }}</button></div>
        </form>
        <div v-if="serviceVipResult" class="inline-callout success" role="status"><strong>{{ t('clusters.serviceVipCreatedTitle') }}</strong><p>{{ serviceVipResult.message }}</p></div>
        <p class="safety-note">{{ t('clusters.templatesSafety') }}</p>
      </section>

      <section v-else-if="activeSection === 'plan'" id="cluster-panel-plan" class="cluster-panel" role="tabpanel" :aria-labelledby="`cluster-tab-${activeSection}`" tabindex="0">
        <div class="panel-heading"><div><span class="eyebrow">{{ t('clusters.guidedSetup') }}</span><h2>{{ t('clusters.planTitle') }}</h2><p>{{ t('clusters.planDescription') }}</p></div><div class="cluster-heading-actions"><span v-if="currentPlanId" class="planned-badge">{{ t('clusters.draftSaved') }}</span><button v-if="clusterPlanType === 'suse-ha'" class="btn role-secondary btn-sm" :disabled="!canManageCluster || planSaving" @click="saveClusterPlan">{{ planSaving ? t('clusters.savingPlan') : t('clusters.savePlan') }}</button><button class="btn role-link btn-sm" @click="startNewPlan">{{ t('clusters.newPlan') }}</button></div></div>
        <div v-if="plansError" class="inline-callout warning" role="alert">{{ plansError }}</div>
        <div v-if="clusterPlanType === 'kvm-virtualization'" class="inline-callout info" role="status"><strong>{{ t('clusters.kvmGroupPlanTitle') }}</strong><p>{{ t('clusters.kvmGroupPlanHelp') }}</p><button class="btn role-primary btn-sm" @click="openManagedKvmClusters">{{ t('clusters.managedKvmClusters') }}</button></div>
        <template v-else>
        <ol class="setup-steps" :aria-label="t('clusters.setupProgress')"><li v-for="(step, index) in setupSteps" :key="step" :class="{ current: setupStep === index, complete: setupStepComplete(index) }"><button type="button" :disabled="!canVisitSetupStep(index)" :aria-current="setupStep === index ? 'step' : undefined" @click="goToSetupStep(index)"><span class="step-number">{{ setupStepComplete(index) ? '✓' : index + 1 }}</span><span class="step-copy"><strong>{{ t(`clusters.setup_${step}`) }}</strong><small>{{ t(`clusters.setup_${step}_help`) }}</small></span></button></li></ol>
        <div class="plan-layout">
          <div class="plan-main">
            <div v-if="selectedTemplateId" class="inline-callout info selected-template-banner"><strong>{{ t('clusters.selectedTemplate', { template: t(`clusters.template_${selectedTemplateId}_title`) }) }}</strong><p>{{ t(`clusters.template_${selectedTemplateId}_description`) }}</p><button class="btn role-link btn-sm" @click="selectedTemplateId = ''">{{ t('clusters.clearTemplate') }}</button></div>
            <section v-if="setupStep === 0" class="setup-stage" aria-labelledby="setup-stage-title">
              <h3 id="setup-stage-title">{{ t('clusters.selectNodes') }}</h3><p class="section-help">{{ t('clusters.selectNodesHelp') }}</p>
              <div v-if="!eligibleHosts.length" class="inline-callout info"><strong>{{ t('clusters.noEligibleHosts') }}</strong><p>{{ t('clusters.noEligibleHostsHelp') }}</p><button class="btn role-link" @click="activeSection = 'overview'">{{ t('clusters.openNodes') }}</button></div>
              <div v-else class="host-picker"><label v-for="host in eligibleHosts" :key="host.id" class="host-option"><input v-model="selectedHostIds" type="checkbox" :value="host.id"><span><strong>{{ host.hostname || host.name }}</strong><small>{{ host.address }} · {{ host.ha?.ha_product_name || host.ha?.ha_product || t('clusters.haEnabled') }}</small></span><span class="state ready"><i></i>{{ t('clusters.readyForPlanning') }}</span></label></div>
              <div v-if="selectedHostIds.length < 2" class="inline-callout info" role="status"><strong>{{ t('clusters.selectAtLeastTwo') }}</strong><p>{{ t('clusters.selectAtLeastTwoHelp') }}</p></div>
            </section>

            <section v-else-if="setupStep === 1" class="setup-stage" aria-labelledby="setup-stage-title">
              <h3 id="setup-stage-title">{{ t('clusters.setup_preflight') }}</h3><p class="section-help">{{ t('clusters.preflightReadOnly') }}</p>
              <div class="preflight-actions"><button class="btn role-primary" :disabled="preflightLoading || selectedHostIds.length < 2" @click="runPreflight()">{{ preflightLoading ? t('clusters.preflightRunning') : t('clusters.runPreflight') }}</button><small>{{ t('clusters.preflightScope', { count: selectedHostIds.length, hosts: selectedHostNames }) }}</small></div>
              <div v-if="preflightError" class="inline-callout warning" role="alert"><strong>{{ t('clusters.preflightError') }}</strong><p>{{ preflightError }}</p></div>
              <div v-if="preflightResults.length" class="preflight-results">
                <h3>{{ t('clusters.preflightResults') }}</h3>
                <article v-for="result in preflightResults" :key="result.host_id" class="preflight-host">
                  <div class="preflight-host-heading"><strong>{{ result.host_name }}</strong><span class="state" :class="result.status === 'checked' ? 'ready' : 'unreachable'"><i></i>{{ result.status === 'checked' ? t('clusters.checked') : t('clusters.checkFailed') }}</span></div>
                  <p v-if="result.error" class="preflight-error-text">{{ result.error }}</p>
                  <template v-else-if="result.checks">
                    <div class="preflight-facts"><span><small>{{ t('clusters.operatingSystem') }}</small><strong>{{ result.checks.os_name || result.checks.os_id || '—' }}</strong></span><span><small>{{ t('clusters.architecture') }}</small><strong>{{ result.checks.architecture || '—' }}</strong></span><span><small>{{ t('clusters.haProduct') }}</small><strong>{{ result.checks.ha_product || t('clusters.haProductUnknown') }}</strong></span><span><small>{{ t('clusters.hostname') }}</small><strong>{{ result.checks.hostname || '—' }}</strong></span></div>
                    <ul class="preflight-checks">
                      <li :class="result.checks.compatibility_supported ? 'check-ok' : 'check-blocked'">{{ result.checks.compatibility_supported ? t('clusters.compatibilitySupported') : t('clusters.compatibilityUnsupported') }}</li>
                      <li :class="result.checks.ha_active ? 'check-ok' : 'check-blocked'">{{ result.checks.ha_active ? t('clusters.haCheckOk') : t('clusters.haCheckMissing') }}</li>
                      <li :class="result.checks.ha_active && result.checks.ha_product ? 'check-ok' : 'check-blocked'">{{ t('clusters.haProductCheck', { product: result.checks.ha_product || t('clusters.haProductUnknown') }) }}</li>
                      <li :class="result.checks.time_synchronized ? 'check-ok' : 'check-warning'">{{ result.checks.time_synchronized ? t('clusters.timeCheckOk') : t('clusters.timeCheckUnknown') }}</li>
                      <li :class="result.checks.tools?.crm && result.checks.tools?.crm_mon ? 'check-ok' : 'check-warning'">{{ result.checks.tools?.crm && result.checks.tools?.crm_mon ? t('clusters.toolsCheckOk') : t('clusters.toolsCheckMissing') }}</li>
                      <li class="check-warning">{{ t('clusters.networkCheckManual', { count: result.checks.interfaces?.length || 0 }) }}</li>
                      <li class="check-warning">{{ result.checks.registered_address_is_dynamic === true ? t('clusters.registeredAddressDynamic') : result.checks.registered_address_is_dynamic === false ? t('clusters.registeredAddressNotMarkedDynamic') : t('clusters.registeredAddressUnknown') }}</li>
                      <li :class="result.checks.watchdog_query?.ok ? 'check-ok' : 'check-warning'">{{ result.checks.watchdog_query?.ok ? t('clusters.watchdogQueryOk', { summary: result.checks.watchdog_query.summary || t('clusters.watchdogQueryNoDetails') }) : result.checks.watchdog_query?.available ? t('clusters.watchdogQueryFailed', { summary: result.checks.watchdog_query.summary || t('clusters.watchdogQueryNoDetails') }) : t('clusters.watchdogQueryUnavailable', { count: result.checks.watchdog_devices?.length || 0 }) }}</li>
                    </ul>
                    <p class="section-help">{{ t('clusters.watchdogQuerySafety') }}</p>
                    <div v-if="result.checks.ssh_peer_connectivity?.length" class="peer-network-check">
                      <strong>{{ t('clusters.sshPeerConnectivityTitle') }}</strong>
                      <p>{{ t('clusters.sshPeerConnectivityScope') }}</p>
                      <ul class="peer-network-checks"><li v-for="peer in result.checks.ssh_peer_connectivity" :key="`${peer.address}:${peer.port}`" :class="peer.reachable && peer.hosts_file_entry_present === true ? 'check-ok' : 'check-warning'">{{ peer.host_name }} ({{ peer.address }}:{{ peer.port }}) · {{ peer.reachable ? t('clusters.sshPeerReachable') : t('clusters.sshPeerUnreachable') }} · {{ peer.hosts_file_entry_present === true ? t('clusters.peerNameMapped') : peer.hosts_file_entry_present === false ? t('clusters.peerNameMissing') : t('clusters.peerNameUnknown') }} · {{ peer.hosts_file_address_matches_ssh_address === true ? t('clusters.peerAddressMatchesSsh') : peer.hosts_file_address_matches_ssh_address === false ? t('clusters.peerAddressDiffersFromSsh') : t('clusters.peerAddressComparisonUnknown') }}<template v-if="peer.hosts_file_addresses?.length"> · {{ t('clusters.peerNameAddresses', { addresses: peer.hosts_file_addresses.join(', ') }) }}</template></li></ul>
                    </div>
                    <div v-if="result.checks.qnetd_tcp_connectivity" class="peer-network-check">
                      <strong>{{ t('clusters.qnetdConnectivityTitle') }}</strong>
                      <p>{{ t('clusters.qnetdConnectivityScope') }}</p>
                      <span :class="result.checks.qnetd_tcp_connectivity.reachable ? 'check-ok' : 'check-warning'">{{ result.checks.qnetd_tcp_connectivity.host }}:{{ result.checks.qnetd_tcp_connectivity.port }}/TCP · {{ result.checks.qnetd_tcp_connectivity.reachable ? t('clusters.qnetdReachable') : t('clusters.qnetdUnreachable') }}</span>
                    </div>
                  </template>
                </article>
                <section v-if="preflightResults.length === selectedHostIds.length && selectedHostIds.length >= 2" class="inline-callout info shared-network-candidates" aria-live="polite">
                  <strong>{{ t('clusters.sharedNetworkCandidatesTitle') }}</strong>
                  <p>{{ sharedNetworkCandidates.length ? t('clusters.sharedNetworkCandidatesHelp') : t('clusters.noSharedNetworkCandidates') }}</p>
                  <ul v-if="sharedNetworkCandidates.length"><li v-for="candidate in sharedNetworkCandidates" :key="candidate.subnet"><code>{{ candidate.subnet }}</code><span v-for="host in candidate.hosts" :key="host.hostName"> · {{ host.hostName }}: {{ host.interfaces.join(', ') || t('clusters.interfaceUnknown') }}</span></li></ul>
                  <p class="section-help">{{ t('clusters.sharedNetworkCandidatesCaveat') }}</p>
                </section>
                <div v-if="preflightCompatibilityWarning" class="inline-callout warning"><strong>{{ t('clusters.compatibilityWarning') }}</strong><p>{{ preflightCompatibilityWarning }}</p></div>
                <div v-if="preflightHaProductWarning" class="inline-callout warning" role="alert"><strong>{{ t('clusters.compatibilityWarning') }}</strong><p>{{ preflightHaProductWarning }}</p></div>
                <div v-if="quorumPlan === 'qdevice' && qnetdHost && !qnetdReachableFromNodes" class="inline-callout info"><strong>{{ t('clusters.qnetdBootstrapTimingTitle') }}</strong><p>{{ t('clusters.qnetdBootstrapTimingHelp') }}</p></div>
                <div v-if="!preflightReadyForBootstrap" class="inline-callout warning"><strong>{{ t('clusters.preflightHasBlockers') }}</strong><p>{{ t('clusters.preflightBlockerHelp') }}</p></div>
              </div>
            </section>

            <section v-else-if="setupStep === 2" class="setup-stage" aria-labelledby="setup-stage-title">
              <h3 id="setup-stage-title">{{ t('clusters.topologyChoices') }}</h3><p class="section-help">{{ t('clusters.topologyChoicesHelp') }}</p>
              <div v-if="recommendedQuorum !== 'unknown'" class="inline-callout info quorum-recommendation">
                <strong>{{ t('clusters.quorumRecommendationTitle', { count: selectedHostIds.length }) }}</strong>
                <p>{{ t(recommendedQuorum === 'qdevice' ? 'clusters.quorumRecommendationQdevice' : 'clusters.quorumRecommendationStandard') }}</p>
                <button v-if="quorumPlan !== recommendedQuorum" class="btn role-secondary btn-sm" @click="applyRecommendedQuorum">{{ t('clusters.applyQuorumRecommendation') }}</button>
              </div>
              <div class="topology-fields"><label>{{ t('clusters.clusterName') }}<input v-model.trim="plannedClusterName" type="text" maxlength="64" :placeholder="t('clusters.clusterNamePlaceholder')" :aria-invalid="plannedClusterName.length > 0 && !validClusterName"></label><label>{{ t('clusters.quorumPlan') }}<select v-model="quorumPlan"><option value="pending">{{ t('clusters.chooseAfterPreflight') }}</option><option value="qdevice">{{ t('clusters.qdevicePlan') }}</option><option value="standard">{{ t('clusters.standardQuorum') }}</option></select></label><label>{{ t('clusters.fencingPlan') }}<select v-model="fencingPlan"><option value="pending">{{ t('clusters.chooseAfterPreflight') }}</option><option value="sbd">{{ t('clusters.sbdPlan') }}</option><option value="hardware">{{ t('clusters.externalFencingPlan') }}</option><option value="manual">{{ t('clusters.fencingPlanLater') }}</option></select></label><label v-if="quorumPlan === 'qdevice'" class="qnetd-field">{{ t('clusters.qnetdHostLabel') }}<input v-model.trim="qnetdHost" type="text" maxlength="253" autocomplete="off" :placeholder="t('clusters.qnetdHostPlaceholder')" :aria-invalid="!qnetdHost.trim() || qnetdMatchesClusterNode"><small>{{ t('clusters.qnetdHostHelp') }}</small></label><label v-if="quorumPlan === 'qdevice'" class="qnetd-confirm"><input v-model="qnetdOutsideCluster" type="checkbox">{{ t('clusters.qnetdOutsideClusterConfirm') }}</label></div>
              <div v-if="fencingPlan === 'manual'" class="inline-callout warning" role="status" aria-live="polite"><strong>{{ t('clusters.fencingRequiredBeforeBootstrapTitle') }}</strong><p>{{ t('clusters.fencingRequiredBeforeBootstrapHelp') }}</p></div>
              <div v-if="fencingReadiness !== 'incomplete'" class="inline-callout info fencing-advisor" role="status" aria-live="polite">
                <strong>{{ t(fencingReadiness === 'sbd-candidate' ? 'clusters.fencingAdvisorSbdTitle' : 'clusters.fencingAdvisorReviewTitle') }}</strong>
                <p>{{ t(fencingReadiness === 'sbd-candidate' ? 'clusters.fencingAdvisorSbdHelp' : 'clusters.fencingAdvisorReviewHelp') }}</p>
                <p v-if="fencingReadiness === 'sbd-candidate' && selectedHostIds.length === 2" class="section-help">{{ t('clusters.fencingAdvisorTwoNodeHelp') }}</p>
                <button v-if="fencingReadiness === 'sbd-candidate' && fencingPlan !== 'sbd'" class="btn role-secondary btn-sm" @click="fencingPlan = 'sbd'">{{ t('clusters.fencingAdvisorChooseSbd') }}</button>
              </div>
              <div v-if="quorumPlan === 'qdevice' && qnetdHost" class="inline-callout info qnetd-guide">
                <strong>{{ t('clusters.qnetdServerChecklistTitle') }}</strong>
                <p>{{ t('clusters.qnetdServerChecklistHelp') }}</p>
                <p><b>{{ t('clusters.qnetdEndpointPromptLabel') }}:</b> <code>{{ qnetdBootstrapEndpoint }}</code></p>
              </div>
              <section v-if="quorumPlan === 'qdevice' && qnetdHost" class="qnetd-host-readiness" aria-live="polite">
                <div class="inline-callout" :class="!qdevicePackagesChecked ? 'info' : qdevicePackageMissingHostIds.length ? 'warning' : 'success'">
                  <strong>{{ t('clusters.qdevicePackagesTitle') }}</strong>
                  <p v-if="!qdevicePackagesChecked">{{ t('clusters.qdevicePackagesNeedPreflight') }}</p>
                  <p v-else-if="qdevicePackageMissingHostIds.length">{{ t('clusters.qdevicePackagesMissing', { hosts: qdevicePackageMissingHostIds.map((id) => selectedClusterHosts.find((host) => host.id === id)?.hostname || selectedClusterHosts.find((host) => host.id === id)?.name || id).join(', ') }) }}</p>
                  <p v-else class="state ready"><i></i>{{ t('clusters.qdevicePackagesInstalled') }}</p>
                  <div v-if="qdevicePackagesChecked && qdevicePackageMissingHostIds.length" class="cluster-heading-actions"><button v-if="!qdevicePackageReview" class="btn role-secondary btn-sm" :disabled="!canManageCluster || preflightLoading || qnetdPrepareLoading" @click="reviewQdevicePackagePreparation">{{ t('clusters.prepareQdevicePackages') }}</button></div>
                  <div v-if="qdevicePackageReview" class="inline-callout warning action-review" role="alert"><strong>{{ t('clusters.qdevicePrepareReviewTitle') }}</strong><p>{{ t('clusters.qdevicePrepareReviewText', { hosts: qdevicePrepareHostNames.join(', ') }) }}</p><small>{{ t('clusters.qdevicePrepareReviewWarning') }}</small><div><button class="btn role-primary btn-sm" :disabled="qnetdPrepareLoading || !canManageCluster" @click="prepareQdevicePackages">{{ qnetdPrepareLoading ? t('clusters.qnetdPreparing') : t('clusters.confirmPrepareQdevice') }}</button><button class="btn role-secondary btn-sm" :disabled="qnetdPrepareLoading" @click="qdevicePackageReview = false; qdevicePrepareHostNames = []">{{ t('clusters.cancelAction') }}</button></div></div>
                  <p v-if="qdevicePrepareError" class="banner error" role="alert">{{ qdevicePrepareError }}</p><ul v-if="qdevicePrepareResults.length" class="operation-results" aria-live="polite"><li v-for="result in qdevicePrepareResults" :key="result.host_id" :class="result.status"><strong>{{ result.host_name }}</strong><span>{{ result.message || (result.error_code ? t(`clusters.${qnetdPrepareErrorKey(result.error_code)}`) : operationStatusText(result.status)) }}</span></li></ul>
                </div>
                <div v-if="qnetdRegisteredWitness" class="inline-callout" :class="qnetdRegisteredWitness.qnetd_package_installed ? 'success' : 'info'">
                  <strong>{{ t('clusters.qnetdStandaloneWitness', { host: qnetdRegisteredWitness.hostname || qnetdRegisteredWitness.name }) }}</strong>
                  <p>{{ qnetdRegisteredWitness.os_name || `${qnetdRegisteredWitness.os_id} ${qnetdRegisteredWitness.os_version}` }} · {{ qnetdRegisteredWitness.username }}@{{ qnetdRegisteredWitness.address }}</p>
                  <p v-if="qnetdRegisteredWitness.status !== 'ready'" class="section-help">{{ t('clusters.qnetdPrepareUnsupported') }}</p>
                  <p v-if="qnetdRegisteredWitness.qnetd_package_installed" class="state ready"><i></i>{{ t('clusters.qnetdPackageInstalled') }}</p>
                  <p v-else>{{ t('clusters.qnetdPackageMissing') }}</p>
                  <p v-if="!qnetdRegisteredWitness.ha_active" class="section-help">{{ t('clusters.qnetdHostHaRequired') }}</p>
                  <p v-else-if="!qnetdRegisteredWitness.time_synchronized" class="section-help">{{ t('clusters.qnetdPrepareTimeSync') }}</p>
                  <p v-else-if="qnetdRegisteredWitness.registered_address_is_dynamic !== false" class="section-help">{{ t('clusters.qnetdPrepareAddress') }}</p>
                  <div class="cluster-heading-actions"><button class="btn role-secondary btn-sm" :disabled="qnetdWitnessRefreshLoading || qnetdPrepareLoading" @click="refreshQnetdWitness">{{ qnetdWitnessRefreshLoading ? t('clusters.qnetdPreparing') : t('clusters.refreshQnetdWitness') }}</button><button v-if="qnetdWitnessEligible" class="btn role-secondary btn-sm" :disabled="qnetdPrepareLoading" @click="qnetdPrepareReview = true">{{ t('clusters.prepareQnetdPackage') }}</button></div>
                  <div v-if="qnetdPrepareReview" class="inline-callout warning action-review" role="alert"><strong>{{ t('clusters.qnetdPrepareReviewTitle') }}</strong><p>{{ t('clusters.qnetdPrepareReviewText', { host: qnetdRegisteredWitness.hostname || qnetdRegisteredWitness.name }) }}</p><small>{{ t('clusters.qnetdPrepareReviewWarning') }}</small><div><button class="btn role-primary btn-sm" :disabled="qnetdPrepareLoading || !qnetdWitnessEligible" @click="prepareQnetdWitnessPackage">{{ qnetdPrepareLoading ? t('clusters.qnetdPreparing') : t('clusters.confirmPrepareQnetd') }}</button><button class="btn role-secondary btn-sm" :disabled="qnetdPrepareLoading" @click="qnetdPrepareReview = false">{{ t('clusters.cancelAction') }}</button></div></div>
                  <div class="cluster-heading-actions"><button class="btn role-link btn-sm" :disabled="qnetdWitnessDeleteLoading" @click="qnetdWitnessDeleteReview = true">{{ t('clusters.removeQnetdWitness') }}</button></div>
                  <div v-if="qnetdWitnessDeleteReview" class="inline-callout warning action-review" role="alert"><strong>{{ t('clusters.removeQnetdWitnessReviewTitle') }}</strong><p>{{ t('clusters.removeQnetdWitnessReviewText', { host: qnetdRegisteredWitness.hostname || qnetdRegisteredWitness.name }) }}</p><div><button class="btn role-danger btn-sm" :disabled="qnetdWitnessDeleteLoading" @click="deleteQnetdWitness">{{ qnetdWitnessDeleteLoading ? t('clusters.qnetdPreparing') : t('clusters.removeQnetdWitness') }}</button><button class="btn role-secondary btn-sm" :disabled="qnetdWitnessDeleteLoading" @click="qnetdWitnessDeleteReview = false">{{ t('clusters.cancelAction') }}</button></div></div>
                  <p v-if="qnetdWitnessError" class="banner error" role="alert">{{ qnetdWitnessError }}</p>
                  <p v-if="qnetdPrepareError" class="banner error" role="alert">{{ qnetdPrepareError }}</p>
                  <p v-if="qnetdPrepareResult" class="inline-callout" :class="qnetdPrepareResult.status === 'installed' || qnetdPrepareResult.status === 'already_installed' ? 'success' : 'warning'" role="status">{{ qnetdPrepareResult.message || (qnetdPrepareResult.error_code ? t(`clusters.${qnetdPrepareErrorKey(qnetdPrepareResult.error_code)}`) : '') }}</p>
                </div>
                <div v-else-if="qnetdRegisteredHost" class="inline-callout" :class="qnetdRegisteredHost.ha?.qnetd_package_installed ? 'success' : 'info'">
                  <strong>{{ t('clusters.qnetdRegisteredHost', { host: qnetdRegisteredHost.hostname || qnetdRegisteredHost.name }) }}</strong>
                  <p v-if="qnetdRegisteredHost.ha?.qnetd_package_installed" class="state ready"><i></i>{{ t('clusters.qnetdPackageInstalled') }}</p>
                  <p v-else>{{ t('clusters.qnetdPackageMissing') }}</p>
                  <p v-if="!qnetdRegisteredHost.ha?.ha_active" class="section-help">{{ t('clusters.qnetdHostHaRequired') }}</p>
                  <div v-if="!qnetdRegisteredHost.ha?.ha_active" class="cluster-heading-actions"><button class="btn role-link btn-sm" @click="goToSubscriptions(qnetdRegisteredHost)">{{ t('clusters.activateHaAddonFirst') }}</button></div>
                  <div v-else-if="qnetdPrepareEligible" class="cluster-heading-actions"><button class="btn role-secondary btn-sm" :disabled="qnetdPrepareLoading" @click="qnetdPrepareReview = true">{{ t('clusters.prepareQnetdPackage') }}</button></div>
                  <div v-if="qnetdPrepareReview" class="inline-callout warning action-review" role="alert"><strong>{{ t('clusters.qnetdPrepareReviewTitle') }}</strong><p>{{ t('clusters.qnetdPrepareReviewText', { host: qnetdRegisteredHost.hostname || qnetdRegisteredHost.name }) }}</p><small>{{ t('clusters.qnetdPrepareReviewWarning') }}</small><div><button class="btn role-primary btn-sm" :disabled="qnetdPrepareLoading || !qnetdPrepareEligible" @click="prepareQnetdPackage">{{ qnetdPrepareLoading ? t('clusters.qnetdPreparing') : t('clusters.confirmPrepareQnetd') }}</button><button class="btn role-secondary btn-sm" :disabled="qnetdPrepareLoading" @click="qnetdPrepareReview = false">{{ t('clusters.cancelAction') }}</button></div></div>
                  <p v-if="qnetdPrepareError" class="banner error" role="alert">{{ qnetdPrepareError }}</p>
                  <p v-if="qnetdPrepareResult" class="inline-callout" :class="qnetdPrepareResult.status === 'installed' || qnetdPrepareResult.status === 'already_installed' ? 'success' : 'warning'" role="status">{{ qnetdPrepareResult.message || (qnetdPrepareResult.error_code ? t(`clusters.${qnetdPrepareErrorKey(qnetdPrepareResult.error_code)}`) : '') }}</p>
                </div>
                <div v-else class="inline-callout info"><strong>{{ t('clusters.qnetdHostNotRegistered') }}</strong><p>{{ t('clusters.qnetdHostNotRegisteredHelp') }}</p></div>
                <details v-if="!qnetdRegisteredWitness && !qnetdRegisteredHost && canManageCluster" class="qnetd-witness-registration">
                  <summary>{{ t('clusters.registerStandaloneQnetd') }}</summary>
                  <p class="section-help">{{ t('clusters.registerStandaloneQnetdHelp') }}</p>
                  <div class="topology-fields">
                    <label>{{ t('clusters.qnetdWitnessName') }}<input v-model.trim="qnetdWitnessDraft.name" maxlength="80" autocomplete="off"></label>
                    <label>{{ t('clusters.qnetdHostLabel') }}<input v-model.trim="qnetdWitnessDraft.address" maxlength="253" autocomplete="off" :placeholder="qnetdHost"></label>
                    <label>{{ t('clusters.sshPort') }}<input v-model.number="qnetdWitnessDraft.port" type="number" min="1" max="65535"></label>
                    <label>{{ t('clusters.sshUsername') }}<input v-model.trim="qnetdWitnessDraft.username" maxlength="128" autocomplete="username"></label>
                    <label>{{ t('clusters.sshPassword') }}<input v-model="qnetdWitnessDraft.password" type="password" maxlength="1024" autocomplete="new-password"></label>
                  </div>
                  <div class="cluster-heading-actions"><button class="btn role-secondary btn-sm" :disabled="qnetdWitnessProbeLoading || qnetdWitnessSaveLoading || !qnetdWitnessDraft.name.trim() || !qnetdWitnessDraft.address.trim()" @click="probeQnetdWitness">{{ qnetdWitnessProbeLoading ? t('clusters.qnetdPreparing') : t('clusters.getQnetdFingerprint') }}</button></div>
                  <div v-if="qnetdWitnessFingerprintIsCurrent" class="inline-callout warning">
                    <p>{{ t('clusters.qnetdFingerprintBeforeCredentials') }}</p>
                    <p><b>{{ t('clusters.sshHostFingerprint') }}:</b> <code>{{ qnetdWitnessProbe.fingerprint }}</code></p>
                    <label class="qnetd-confirm"><input v-model="qnetdWitnessFingerprintConfirmed" type="checkbox">{{ t('clusters.confirmQnetdFingerprint') }}</label>
                    <div v-if="!qnetdWitnessProbeIsCurrent" class="cluster-heading-actions"><button class="btn role-secondary btn-sm" :disabled="!qnetdWitnessFingerprintConfirmed || qnetdWitnessProbeLoading || !qnetdWitnessDraft.password || !qnetdWitnessDraft.username.trim()" @click="verifyQnetdWitness">{{ qnetdWitnessProbeLoading ? t('clusters.qnetdPreparing') : t('clusters.verifyQnetdWitness') }}</button></div>
                    <div v-if="qnetdWitnessProbeIsCurrent" class="inline-callout" :class="qnetdWitnessProbe.facts.ha_active && qnetdWitnessProbe.facts.compatibility_supported ? 'success' : 'warning'">
                      <strong>{{ t('clusters.qnetdWitnessProbeComplete', { host: qnetdWitnessProbe.facts.hostname }) }}</strong>
                      <p>{{ qnetdWitnessProbe.facts.os_name }} · {{ qnetdWitnessProbe.facts.os_version }} · {{ qnetdWitnessProbe.facts.ha_product || t('clusters.qnetdHaInactive') }}</p>
                      <p>{{ t('clusters.qnetdWitnessPackageState', { state: qnetdWitnessProbe.facts.qnetd_package_installed ? t('clusters.qnetdPackageInstalled') : t('clusters.qnetdPackageMissing') }) }}</p>
                      <div class="cluster-heading-actions"><button class="btn role-primary btn-sm" :disabled="!qnetdWitnessFingerprintConfirmed || qnetdWitnessSaveLoading" @click="registerQnetdWitness">{{ qnetdWitnessSaveLoading ? t('clusters.qnetdPreparing') : t('clusters.saveQnetdWitness') }}</button></div>
                    </div>
                  </div>
                  <p v-if="qnetdWitnessError" class="banner error" role="alert">{{ qnetdWitnessError }}</p>
                </details>
              </section>
              <section class="corosync-network-plan" aria-labelledby="corosync-plan-title">
                <h4 id="corosync-plan-title">{{ t('clusters.corosyncPlanTitle') }}</h4><p class="section-help">{{ t('clusters.corosyncPlanHelp') }}</p>
                <div v-if="!preflightComplete" class="inline-callout info">{{ t('clusters.preflightRequiredForBootstrap') }}</div>
                <div v-else class="corosync-network-fields">
                  <label>{{ t('clusters.corosyncRing0Label') }}<select v-model="corosyncRing0"><option value="">{{ t('clusters.corosyncManualChoice') }}</option><option v-for="candidate in sharedNetworkCandidates" :key="candidate.subnet" :value="candidate.subnet">{{ corosyncCandidateLabel(candidate) }}</option></select></label>
                  <label>{{ t('clusters.corosyncRing1Label') }}<select v-model="corosyncRing1"><option value="">{{ t('clusters.corosyncNoSecondChannel') }}</option><option v-for="candidate in sharedNetworkCandidates.filter((item) => item.subnet !== corosyncRing0)" :key="candidate.subnet" :value="candidate.subnet">{{ corosyncCandidateLabel(candidate) }}</option></select></label>
                </div>
                <div v-for="candidate in selectedCorosyncNetworkCandidates.filter((item) => item.dynamicHosts.length)" :key="`dynamic-${candidate.subnet}`" class="inline-callout warning" role="alert">{{ t('clusters.corosyncNetworkDynamicWarning', { hosts: candidate.dynamicHosts.join(', ') }) }} · {{ candidate.subnet }}</div>
                <div v-if="selectedCorosyncNetworkUnavailable" class="inline-callout warning" role="alert">{{ t('clusters.corosyncNetworkUnavailable') }}</div>
                <label class="corosync-network-confirm"><input v-model="corosyncNetworkReviewed" type="checkbox"><span><strong>{{ t('clusters.corosyncNetworkConfirm') }}</strong><small>{{ t('clusters.corosyncNetworkConfirmHelp') }}</small></span></label>
              </section>
              <div v-if="plannedClusterName && !validClusterName" class="inline-callout warning" role="alert"><strong>{{ t('clusters.clusterNameInvalid') }}</strong></div>
              <div v-if="quorumPlan === 'qdevice' && qnetdMatchesClusterNode" class="inline-callout warning" role="alert"><strong>{{ t('clusters.qnetdMustBeExternal') }}</strong><p>{{ t('clusters.qnetdHostHelp') }}</p></div>
              <div v-if="selectedHostIds.length === 2" class="inline-callout warning" role="note"><strong>{{ t('clusters.twoNodeTitle') }}</strong><p>{{ t('clusters.twoNodeHelp') }}</p><p>{{ t('clusters.qnetdPlacement') }}</p></div><div v-else-if="selectedHostIds.length > 2 && selectedHostIds.length % 2 === 0" class="inline-callout info" role="note"><strong>{{ t('clusters.evenNodeTitle') }}</strong><p>{{ t('clusters.evenNodeHelp') }}</p><p>{{ t('clusters.qnetdPlacement') }}</p></div><div v-else-if="selectedHostIds.length >= 3" class="inline-callout success" role="status"><strong>{{ t('clusters.oddNodeTitle') }}</strong><p>{{ t('clusters.oddNodeHelp') }}</p></div>
              <div class="practice-grid"><article><span class="practice-mark">✓</span><div><strong>{{ t('clusters.practiceFailureDomains') }}</strong><p>{{ t('clusters.practiceFailureDomainsHelp') }}</p></div></article><article><span class="practice-mark">✓</span><div><strong>{{ t('clusters.practiceFencing') }}</strong><p>{{ t('clusters.practiceFencingHelp') }}</p></div></article><article><span class="practice-mark">✓</span><div><strong>{{ t('clusters.practiceNetwork') }}</strong><p>{{ t('clusters.practiceNetworkHelp') }}</p></div></article></div>
              <article v-if="selectedTemplateId" class="template-plan-preview"><span class="eyebrow">{{ t('clusters.templatePlanPreview') }}</span><h4>{{ t(`clusters.template_${selectedTemplateId}_title`) }}</h4><p>{{ t('clusters.templatePlanPreviewHelp') }}</p><ul><li v-for="item in templatePreviewItems(selectedTemplateId)" :key="item">{{ item }}</li></ul></article>
              <div class="inline-callout info"><strong>{{ t('clusters.planOnlyLabel') }}</strong><p>{{ t('clusters.topologyChoicesHelp') }}</p></div>
            </section>

            <section v-else-if="setupStep === 3" class="setup-stage" aria-labelledby="setup-stage-title">
              <h3 id="setup-stage-title">{{ t('clusters.reviewBeforeChanges') }}</h3><p class="section-help">{{ t('clusters.reviewBeforeChangesHelp') }}</p>
              <div class="review-grid"><article><h4>{{ t('clusters.reviewHosts') }}</h4><ul><li v-for="host in selectedClusterHosts" :key="host.id">{{ host.hostname || host.name }} <span>{{ host.address }}</span></li></ul></article><article><h4>{{ t('clusters.reviewTopology') }}</h4><dl><dt>{{ t('clusters.clusterName') }}</dt><dd>{{ plannedClusterName }}</dd><dt>{{ t('clusters.quorum') }}</dt><dd>{{ t(`clusters.quorum_${quorumPlan}`) }}</dd><template v-if="quorumPlan === 'qdevice'"><dt>{{ t('clusters.qnetdHostLabel') }}</dt><dd>{{ qnetdHost }}</dd><dt>{{ t('clusters.qnetdEndpointPromptLabel') }}</dt><dd><code>{{ qnetdBootstrapEndpoint }}</code></dd><dt>{{ t('clusters.qnetdPlacementLabel') }}</dt><dd>{{ qnetdOutsideCluster ? t('clusters.qnetdExternalConfirmed') : t('clusters.qnetdExternalUnconfirmed') }}</dd></template><dt>{{ t('clusters.fencing') }}</dt><dd>{{ t(`clusters.fencing_${fencingPlan}`) }}</dd><dt>{{ t('clusters.corosyncRing0Label') }}</dt><dd>{{ corosyncRing0 || t('clusters.corosyncNetworkNoSelection') }}</dd><dt>{{ t('clusters.corosyncRing1Label') }}</dt><dd>{{ corosyncRing1 || t('clusters.corosyncNoSecondChannel') }}</dd><dt>{{ t('clusters.corosyncNetworkConfirm') }}</dt><dd>{{ corosyncNetworkReviewed ? t('clusters.corosyncNetworkReviewedYes') : t('clusters.corosyncNetworkReviewedNo') }}</dd><dt>{{ t('clusters.summaryNetworks') }}</dt><dd>{{ t('clusters.networkCheckManualSummary') }}</dd></dl></article><article v-if="selectedTemplateId" class="template-plan-preview"><h4>{{ t('clusters.templatePlanPreview') }} · {{ t(`clusters.template_${selectedTemplateId}_title`) }}</h4><ul><li v-for="item in templatePreviewItems(selectedTemplateId)" :key="item">{{ item }}</li></ul></article></div>
              <div v-for="candidate in selectedCorosyncNetworkCandidates.filter((item) => item.dynamicHosts.length)" :key="`review-dynamic-${candidate.subnet}`" class="inline-callout warning" role="alert">{{ t('clusters.corosyncNetworkDynamicWarning', { hosts: candidate.dynamicHosts.join(', ') }) }} · {{ candidate.subnet }}</div>
              <div class="inline-callout" :class="preflightReadyForBootstrap ? 'success' : 'warning'"><strong>{{ preflightReadyForBootstrap ? t('clusters.preflightReadyTitle') : t('clusters.preflightHasBlockers') }}</strong><p>{{ preflightReadyForBootstrap ? t('clusters.preflightReadyHelp') : t('clusters.preflightBlockerHelp') }}</p></div>
              <div class="stack-install"><div><strong>{{ t('clusters.installHaStackTitle') }}</strong><p>{{ haStackMissingHosts.length ? t('clusters.haStackMissingCount', { count: haStackMissingHosts.length, hosts: haStackMissingHostNames }) : t('clusters.haStackInstalledOnAll') }}</p></div><button v-if="canManageCluster && haStackMissingHosts.length" class="btn role-secondary" :disabled="stackInstallLoading || pendingInstallStack" @click="pendingInstallStack = true">{{ stackInstallLoading ? t('clusters.stackInstallRunning') : t('clusters.installHaStack') }}</button><span v-else-if="!canManageCluster" class="planned-badge">{{ t('clusters.operatorRoleRequired') }}</span><span v-else class="state ready"><i></i>{{ t('clusters.stackInstalled') }}</span></div>
              <div v-if="pendingInstallStack" class="inline-callout warning action-review"><strong>{{ t('clusters.installReviewTitle') }}</strong><p>{{ t('clusters.installReviewText', { hosts: haStackMissingHostNames }) }}</p><small>{{ t('clusters.installReviewWarning') }}</small><div><button class="btn role-primary btn-sm" :disabled="stackInstallLoading" @click="installHaStack">{{ stackInstallLoading ? t('clusters.stackInstallRunning') : t('clusters.confirmInstallHaStack') }}</button><button class="btn role-secondary btn-sm" :disabled="stackInstallLoading" @click="pendingInstallStack = false">{{ t('clusters.cancelAction') }}</button></div></div>
              <div v-if="stackInstallResults.length" class="preflight-results"><h3>{{ t('clusters.stackInstallResults') }}</h3><article v-for="item in stackInstallResults" :key="item.host_id" class="preflight-host"><div class="preflight-host-heading"><strong>{{ item.host_name }}</strong><span class="state" :class="item.status === 'installed' ? 'ready' : 'unreachable'"><i></i>{{ item.status === 'installed' ? t('clusters.stackInstalled') : t('clusters.stackInstallFailed') }}</span></div><p v-if="item.error" class="preflight-error-text">{{ item.error }}</p><p v-else class="section-help">{{ item.message }}</p></article></div>
              <div v-if="!validClusterName || quorumPlan === 'pending' || fencingPlan === 'pending' || fencingPlan === 'manual' || !corosyncNetworkPlanReady" class="inline-callout warning"><strong>{{ t('clusters.reviewIncomplete') }}</strong><p>{{ t('clusters.reviewIncompleteHelp') }}</p></div><p class="safety-note">{{ t('clusters.planSafety') }}</p>
            </section>

            <section v-else class="setup-stage" aria-labelledby="setup-stage-title">
              <h3 id="setup-stage-title">{{ t('clusters.bootstrapTitle') }}</h3><p class="section-help">{{ t('clusters.bootstrapHelp') }}</p>
              <div v-if="bootstrapUserMismatch" class="inline-callout warning" role="alert"><strong>{{ t('clusters.bootstrapUserMismatchTitle') }}</strong><p>{{ t('clusters.bootstrapUserMismatchHelp') }}</p></div>
              <div v-else-if="!canStartBootstrap" class="inline-callout warning"><strong>{{ t('clusters.preflightRequiredForBootstrap') }}</strong><p>{{ t('clusters.bootstrapRequirements') }}</p></div>
              <div v-else class="bootstrap-guide">
                <div class="inline-callout info"><strong>{{ t('clusters.corosyncPromptLabel') }}</strong><p>{{ t('clusters.corosyncNetworkBootstrapInstruction') }}</p><ul><li><strong>ring0:</strong> {{ corosyncRing0 || t('clusters.corosyncNetworkNoSelection') }}</li><li><strong>ring1:</strong> {{ corosyncRing1 || t('clusters.corosyncNoSecondChannel') }}</li></ul></div>
                <article>
                  <div><strong>1 · {{ t('clusters.initializeFirstNode', { host: selectedClusterHosts[0].hostname || selectedClusterHosts[0].name }) }}</strong><button class="btn role-secondary btn-sm" @click="copyBootstrapCommand(initCommand)">{{ t('clusters.copyCommand') }}</button><button class="btn role-primary btn-sm" :disabled="bootstrapPreparing || !canBootstrapOperation(selectedClusterHosts[0], 'init')" @click="prepareClusterBootstrap(selectedClusterHosts[0], 'init')">{{ bootstrapPreparing ? t('clusters.bootstrapPreparing') : t('clusters.reviewBootstrap') }}</button></div>
                  <code>{{ initCommand }}</code>
                </article>
                <div class="inline-callout info bootstrap-join-progress" role="status" aria-live="polite">
                  <strong>{{ bootstrapJoinProgressText }}</strong>
                  <p v-if="!bootstrapJoinProgress.initialized">{{ t('clusters.bootstrapJoinWaitingForInit') }}</p>
                  <p v-else-if="nextBootstrapJoinHost">{{ t('clusters.bootstrapJoinNext', { host: nextBootstrapJoinHost.hostname || nextBootstrapJoinHost.name }) }}</p>
                  <p v-else>{{ t('clusters.bootstrapJoinComplete') }}</p>
                </div>
                <article v-for="host in selectedClusterHosts.slice(1)" :key="host.id">
                  <div><strong>{{ t('clusters.joinAdditionalNode', { host: host.hostname || host.name }) }}</strong><span class="bootstrap-node-state" :class="`is-${bootstrapJoinNodeState(host)}`">{{ t(`clusters.bootstrapJoinStatus_${bootstrapJoinNodeState(host)}`) }}</span><button class="btn role-secondary btn-sm" @click="copyBootstrapCommand(joinCommand())">{{ t('clusters.copyCommand') }}</button><button class="btn role-primary btn-sm" :disabled="bootstrapPreparing || !canBootstrapOperation(host, 'join')" @click="prepareClusterBootstrap(host, 'join')">{{ bootstrapPreparing ? t('clusters.bootstrapPreparing') : host.id === bootstrapJoinProgress.nextHostId ? t('clusters.reviewNextJoinNode') : t('clusters.reviewBootstrap') }}</button></div>
                  <code>{{ joinCommand() }}</code>
                </article>
                <article v-if="quorumPlan === 'qdevice'">
                  <div><strong>{{ selectedClusterHosts.length + 1 }} · {{ t('clusters.configureQdevice') }}</strong><button class="btn role-secondary btn-sm" @click="copyBootstrapCommand(qdeviceCommand)">{{ t('clusters.copyCommand') }}</button><button class="btn role-primary btn-sm" :disabled="bootstrapPreparing || !canBootstrapOperation(selectedClusterHosts[0], 'qdevice')" @click="prepareClusterBootstrap(selectedClusterHosts[0], 'qdevice')">{{ bootstrapPreparing ? t('clusters.bootstrapPreparing') : t('clusters.reviewBootstrap') }}</button></div>
                  <code>{{ qdeviceCommand }}</code><small>{{ t('clusters.qdeviceConfigureRisk') }}</small><small v-if="!qdeviceReadyForBootstrap">{{ t('clusters.qdeviceConfigurePrerequisites') }}</small>
                </article>
                <span v-if="copyFeedback" role="status" class="copy-feedback">{{ copyFeedback }}</span>
              </div>
              <div v-if="pendingBootstrap" class="inline-callout warning action-review" role="alert"><strong>{{ t('clusters.bootstrapReviewTitle') }}</strong><p>{{ t('clusters.bootstrapReviewText', { operation: t(pendingBootstrap.operation === 'init' ? 'clusters.bootstrapInitialize' : pendingBootstrap.operation === 'join' ? 'clusters.bootstrapJoin' : 'clusters.bootstrapConfigureQdevice'), host: pendingBootstrap.host.hostname || pendingBootstrap.host.name }) }}</p><code>{{ pendingBootstrap.command }}</code><p>{{ pendingBootstrap.operation === 'qdevice' ? t('clusters.qdeviceConfigureReviewWarning') : t('clusters.bootstrapReviewWarning') }}</p><div><button class="btn role-primary btn-sm" :disabled="bootstrapPreparing" @click="confirmClusterBootstrap">{{ bootstrapPreparing ? t('clusters.bootstrapPreparing') : t('clusters.bootstrapConfirm') }}</button><button class="btn role-secondary btn-sm" :disabled="bootstrapPreparing" @click="pendingBootstrap = null">{{ t('clusters.cancelAction') }}</button></div></div>
              <VmConsole v-if="bootstrapTerminalHost && bootstrapTerminalPlanId" :host-id="bootstrapTerminalHost.id" :vm-name="bootstrapTerminalHost.hostname || bootstrapTerminalHost.name" :host-terminal="true" :cluster-bootstrap-plan-id="bootstrapTerminalPlanId" :cluster-bootstrap-operation="bootstrapTerminalOperation" @close="closeBootstrapTerminal" />
              <div class="inline-callout warning"><strong>{{ t('clusters.bootstrapInteractiveTitle') }}</strong><p>{{ t('clusters.bootstrapInteractiveHelp', { quorum: t(`clusters.quorum_${quorumPlan}`), fencing: t(`clusters.fencing_${fencingPlan}`) }) }}</p><p>{{ t('clusters.bootstrapFirewallHelp') }}</p><p v-if="quorumPlan === 'qdevice'"><strong>{{ t('clusters.qnetdHostLabel') }}:</strong> <code>{{ qnetdBootstrapEndpoint }}</code> · {{ t('clusters.qnetdBootstrapReminder') }}</p></div><p class="safety-note">{{ t('clusters.bootstrapSafety') }}</p>
            </section>
          </div>
          <aside class="plan-summary"><span class="eyebrow">{{ t('clusters.setupStatus') }}</span><strong>{{ setupStep + 1 }} / {{ setupSteps.length }}</strong><p>{{ t(`clusters.setup_${setupSteps[setupStep]}`) }}</p><div class="summary-divider"></div><p><b>{{ t('clusters.reviewHosts') }}:</b> {{ selectedHostIds.length }} {{ t('clusters.selectedNodes') }}</p><p><b>{{ t('clusters.clusterName') }}:</b> {{ plannedClusterName || t('clusters.notChosen') }}</p><p><b>{{ t('clusters.quorum') }}:</b> {{ t(`clusters.quorum_${quorumPlan}`) }}</p><p><b>{{ t('clusters.fencing') }}:</b> {{ t(`clusters.fencing_${fencingPlan}`) }}</p><span class="state" :class="preflightReadyForBootstrap ? 'ready' : 'warning-state'"><i></i>{{ preflightReadyForBootstrap ? t('clusters.preflightReadyTitle') : t('clusters.preflightPendingLabel') }}</span></aside>
        </div>
        <footer class="setup-footer"><button class="btn role-secondary" :disabled="setupStep === 0" @click="goToSetupStep(setupStep - 1)">{{ t('clusters.previousStep') }}</button><span>{{ t('clusters.setupStepCounter', { current: setupStep + 1, total: setupSteps.length }) }}</span><button v-if="setupStep < setupSteps.length - 1" class="btn role-primary" :disabled="!canVisitSetupStep(setupStep + 1)" @click="goToSetupStep(setupStep + 1)">{{ t('clusters.nextStep') }}</button><button v-else class="btn role-primary" :disabled="loading" @click="checkClusterAfterSetup">{{ t('clusters.checkClusterStatus') }}</button></footer>
        </template>
