    serviceVipReady(): boolean { const draft = this.serviceVipDraft; const status = this.clusterStatus; return Boolean(this.canManageCluster && draft && status && status.node_count >= 2 && status.quorum?.quorate && status.fencing?.configured && draft.service_unit.trim().endsWith('.service') && (draft.profile !== 'apache' || (draft.apache_configfile.trim().startsWith('/') && draft.apache_start_order_confirmed)) && draft.virtual_ip.trim() && draft.shared_network_confirmed); },
    serviceVipSummary(): string { const draft = this.serviceVipDraft; if (!draft) return ''; return draft.profile === 'apache' ? this.t('clusters.apacheReviewSummary', { prefix: draft.resource_prefix, unit: draft.service_unit, configfile: draft.apache_configfile, vip: `${draft.virtual_ip}/${draft.cidr_netmask}` }) : this.t('clusters.serviceVipReviewSummary', { prefix: draft.resource_prefix, unit: draft.service_unit, vip: `${draft.virtual_ip}/${draft.cidr_netmask}` }); },
    recommendedQuorum(): ReturnType<typeof recommendedClusterQuorum> { return recommendedClusterQuorum(this.selectedHostIds.length); },
    fencingReadiness(): ReturnType<typeof clusterFencingReadiness> { return clusterFencingReadiness(this.preflightResults, this.selectedHostIds.length); },
    availableSections(): string[] { const liveClusterSections = ['nodes','resources','constraints','activity','fencing']; return this.sections.filter((section) => !liveClusterSections.includes(section) || Boolean(this.clusterStatus)); },
    clusterHosts(): Host[] { const seen = new Set<string>(); return this.hosts.filter((host) => { const identity = host.ha?.cluster_identity; if (!host.ha?.cluster_detected || !identity) return false; if (seen.has(identity)) return false; seen.add(identity); return true; }); },
    unregisteredClusterHosts(): Host[] { return this.clusterHosts.filter((host) => !this.managedSuseHaClusters.some((cluster) => this.sameManagedHaCluster(cluster, host))); },
    templateCandidateHosts(): Host[] { return this.hosts.filter((host) => host.status === 'ready' && !host.ha?.cluster_detected); },
    quorumSummary(): string { const value = this.clusterStatus?.quorum?.summary?.split('\n').find((line) => /quorate|quorum|votes|expected/i.test(line)); return value?.trim() || this.t('clusters.quorumHelp'); },
    fencingSummary(): string { const fencing = this.clusterStatus?.fencing; if (fencing?.sbd?.configured) return this.t('clusters.fencingSbdSummary', { type: fencing.sbd.type || 'SBD', host: this.clusterStatus?.source_host_name || '' }); if (fencing?.mechanism) return fencing.mechanism; const value = fencing?.summary?.trim(); return value ? value.split('\n').slice(0,2).join(' · ') : this.t('clusters.fencingHelp'); },
    groupableResources(): ClusterResource[] { return (this.clusterStatus?.resources || []).filter((resource) => resource.managed && resource.agent !== 'group' && resource.agent !== 'clone' && resource.agent !== 'promotable clone' && resource.agent !== 'stonith' && !resource.agent?.startsWith('stonith:') && !resource.parent_id && !resource.group_id && !resource.active); },
    cloneableResources(): ClusterResource[] { return (this.clusterStatus?.resources || []).filter((resource) => resource.agent === 'group' ? resource.managed && !resource.parent_id && !resource.active : this.groupableResources.some((candidate) => candidate.id === resource.id)); },
    actionReviewText(): string { if (!this.pendingClusterAction) return ''; return this.t(`clusters.review_${this.pendingClusterAction.action}`, { target: this.pendingClusterAction.target }); },
    resourceMutationSummary(): string { const change = this.pendingResourceMutation; if (!change) return ''; if (change.action === 'create_stonith') return this.t('clusters.reviewCreateFencing', { id: change.resource_id, agent: change.agent || '', node: change.fencing_target || '', count: Object.keys(change.parameters || {}).length }); if (change.action === 'edit_stonith') return this.t('clusters.reviewEditFencing', { id: change.resource_id, node: change.fencing_target || '', changes: Object.keys(change.parameters || {}).length, removals: change.parameter_removals?.length || 0 }); if (change.action === 'delete_stonith') return this.t('clusters.reviewDeleteFencing', { id: change.resource_id }); if (change.action === 'create_clone') return this.t('clusters.reviewCreateClone', { id: change.resource_id, resource: change.child_id || '', kind: this.t(change.clone_type === 'promotable' ? 'clusters.clonePromotable' : 'clusters.cloneStandard').toLowerCase() }); if (change.action === 'delete_clone') return this.t('clusters.reviewDeleteClone', { id: change.resource_id, child: change.child_id || '' }); if (change.action === 'edit_clone') { const options = Object.entries(change.clone_metadata || {}).filter(([key, value]) => value !== (change.expected_clone_metadata || {})[key]).map(([key, value]) => value ? `${key}=${value}` : `${key} (${this.t('clusters.cloneOptionDefault').toLowerCase()})`).join(', '); return this.t('clusters.reviewEditClone', { id: change.resource_id, options }); } if (change.action === 'create_group') return this.t('clusters.reviewCreateGroup', { id: change.resource_id, members: (change.children || []).join(' → ') }); if (change.action === 'delete_group') return this.t('clusters.reviewDeleteGroup', { id: change.resource_id, members: (change.children || []).join(', ') }); if (change.action === 'reorder_group') return this.t('clusters.reviewReorderGroup', { id: change.resource_id, members: (change.children || []).join(' → ') }); if (change.action === 'add_group_member') return this.t('clusters.reviewAddGroupMember', { resource: change.child_id || '', group: change.resource_id }); if (change.action === 'remove_group_member') return this.t('clusters.reviewRemoveGroupMember', { resource: change.child_id || '', group: change.resource_id }); if (change.action === 'create') return this.t('clusters.reviewCreateResource', { id: change.resource_id, agent: change.agent || '', count: Object.keys(change.parameters || {}).length, monitorCount: change.operations?.length || 0 }); if (change.action === 'set_monitor_ops') return this.t('clusters.reviewMonitorOperations', { id: change.resource_id, count: change.operations?.length || 0 }); if (change.action === 'delete') return this.t('clusters.reviewDeleteResource', { id: change.resource_id }); return this.t('clusters.reviewEditResource', { id: change.resource_id, attribute: change.key || '', action: change.action.startsWith('delete_') ? this.t('clusters.deleteAttribute').toLowerCase() : this.t('clusters.updateAttribute').toLowerCase() }); },
    constraintMutationSummary(): string { const change = this.pendingConstraintMutation; if (!change) return ''; if (change.action === 'delete') return this.t('clusters.reviewDeleteConstraint', { id: change.constraint_id }); return this.t('clusters.reviewCreateConstraint', { id: change.constraint_id, kind: this.t(`clusters.${change.action}`), resource: change.resource, other: change.other_resource || change.node || '', score: change.score || '' }); },
    selectedHostNames(): string { return this.hosts.filter((host) => this.selectedHostIds.includes(host.id)).map((host) => host.hostname || host.name).join(', '); },
    selectedClusterHosts(): Host[] { return this.selectedHostIds.map((id) => this.hosts.find((host) => host.id === id)).filter((host): host is Host => Boolean(host)); },
    currentPlanHostIds(): string[] { return this.clusterPlans.find((plan) => plan.id === this.currentPlanId)?.host_ids || []; },
    selectedTemplateHosts(): Host[] { return this.templateHostIds.map((id) => this.hosts.find((host) => host.id === id)).filter((host): host is Host => Boolean(host)); },
    haStackMissingHosts(): Host[] { return this.selectedClusterHosts.filter((host) => !this.haToolsInstalled(host)); },
    qnetdRegisteredHost(): Host | null { const endpoint = this.qnetdHost.trim().toLowerCase().replace(/\.$/, ''); if (!endpoint) return null; const matches = this.hosts.filter((host) => !this.selectedHostIds.includes(host.id) && [host.name, host.hostname, host.address].some((value) => value?.trim().toLowerCase().replace(/\.$/, '') === endpoint)); return matches.length === 1 ? matches[0] : null; },
    qnetdRegisteredWitness(): QnetdWitness | null { const endpoint = this.qnetdHost.trim().toLowerCase().replace(/\.$/, ''); if (!endpoint) return null; const matches = this.qnetdWitnesses.filter((witness) => [witness.hostname, witness.address].some((value) => value?.trim().toLowerCase().replace(/\.$/, '') === endpoint)); return matches.length === 1 ? matches[0] : null; },
    qnetdWitnessEligible(): boolean { const witness = this.qnetdRegisteredWitness; return Boolean(this.canManageCluster && witness && witness.status === 'ready' && witness.ha_active && witness.time_synchronized && witness.registered_address_is_dynamic === false && !witness.qnetd_package_installed); },
    qnetdWitnessFingerprintIsCurrent(): boolean { return Boolean(this.qnetdWitnessProbe && this.qnetdWitnessFingerprintSignature === qnetdWitnessFingerprintSignature(this.qnetdWitnessDraft)); },
    qnetdWitnessProbeIsCurrent(): boolean { return Boolean(this.qnetdWitnessFingerprintIsCurrent && this.qnetdWitnessProbe?.facts && this.qnetdWitnessProbeSignature === JSON.stringify(this.qnetdWitnessDraft)); },
    qnetdPrepareEligible(): boolean { const host = this.qnetdRegisteredHost; return Boolean(this.canManageCluster && host && host.status === 'ready' && host.ha?.ha_active && host.ha?.qnetd_package_installed === false); },
    qnetdPrepareErrorKey(code: string): string { const keys: Record<string, string> = { qnetd_host_unsupported: 'qnetdPrepareUnsupported', qnetd_host_ha_inactive: 'qnetdHostHaRequired', qnetd_host_time_sync: 'qnetdPrepareTimeSync', qnetd_host_address_unstable: 'qnetdPrepareAddress', qdevice_node_unavailable: 'qnetdPreparePlanChanged', qnetd_prepare_failed: 'qnetdPrepareFailed', qnetd_plan_changed: 'qnetdPreparePlanChanged' }; return keys[code] || 'qnetdPrepareFailed'; },
    qdevicePackagesChecked(): boolean { return this.selectedHostIds.length >= 2 && this.preflightResults.length === this.selectedHostIds.length && this.selectedHostIds.every((id) => { const result = this.preflightResults.find((item) => item.host_id === id); return result?.status === 'checked' && typeof result.checks?.qdevice_package_installed === 'boolean'; }); },
    qdevicePackageMissingHostIds(): string[] { return this.selectedHostIds.filter((id) => this.preflightResults.find((result) => result.host_id === id)?.checks?.qdevice_package_installed === false); },
    reviewQdevicePackagePreparation() { this.qdevicePrepareHostNames = this.qdevicePackageMissingHostIds.map((id) => { const host = this.selectedClusterHosts.find((item) => item.id === id); return host?.hostname || host?.name || id; }); this.qdevicePackageReview = true; },
    haStackMissingHostNames(): string { return this.haStackMissingHosts.map((host) => host.hostname || host.name).join(', '); },
    validClusterName(): boolean { return /^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/.test(this.plannedClusterName); },
    preflightComplete(): boolean { return this.selectedHostIds.length >= 2 && this.selectedHostIds.every((id) => this.preflightResults.some((result) => result.host_id === id)); },
    sharedNetworkCandidates(): ReturnType<typeof sharedCorosyncNetworkCandidates> { const selected = this.selectedHostIds.map((id) => this.preflightResults.find((result) => result.host_id === id)).filter((result): result is PreflightResult => Boolean(result)); return sharedCorosyncNetworkCandidates(selected.map((result) => ({ host_name: result.host_name, status: result.status, checks: { interfaces: result.checks?.interfaces } })), this.selectedHostIds.length); },
    selectedCorosyncNetworkCandidates(): ReturnType<typeof sharedCorosyncNetworkCandidates> { const selected = new Set([this.corosyncRing0, this.corosyncRing1].filter(Boolean)); return this.sharedNetworkCandidates.filter((candidate) => selected.has(candidate.subnet)); },
    selectedCorosyncNetworkUnavailable(): boolean { const candidates = new Set(this.sharedNetworkCandidates.map((candidate) => candidate.subnet)); return [this.corosyncRing0, this.corosyncRing1].filter(Boolean).some((subnet) => !candidates.has(subnet)); },
    corosyncNetworkPlanReady(): boolean { return isCorosyncNetworkPlanReady(this.corosyncRing0, this.corosyncRing1, this.corosyncNetworkReviewed, this.sharedNetworkCandidates.map((candidate) => candidate.subnet)); },
    sharedTemplateNetworkCandidates(): ReturnType<typeof sharedCorosyncNetworkCandidates> { const selected = this.templateHostIds.map((id) => this.preflightResults.find((result) => result.host_id === id)).filter((result): result is PreflightResult => Boolean(result)); return sharedCorosyncNetworkCandidates(selected.map((result) => ({ host_name: result.host_name, status: result.status, checks: { interfaces: result.checks?.interfaces } })), this.templateHostIds.length); },
    topologyReady(): boolean { return this.corosyncNetworkPlanReady && isClusterTopologyReady({ name: this.plannedClusterName, quorum: this.quorumPlan, fencing: this.fencingPlan, qnetdHost: this.qnetdHost, qnetdOutsideCluster: this.qnetdOutsideCluster, nodeNames: this.selectedClusterHosts.flatMap((host) => [host.name, host.hostname || '']), nodeAddresses: this.selectedClusterHosts.map((host) => host.address) }); },
    qnetdMatchesClusterNode(): boolean { const witness = this.qnetdHost.trim().toLowerCase(); return Boolean(witness && this.selectedClusterHosts.some((host) => [host.address, host.name, host.hostname || ''].some((value) => value.trim().toLowerCase() === witness))); },
    qnetdBootstrapEndpoint(): string { return qnetdBootstrapEndpoint(this.qnetdRegisteredWitness?.username || this.selectedClusterHosts[0]?.username || '', this.qnetdHost); },
    qnetdReachableFromNodes(): boolean { return this.quorumPlan !== 'qdevice' || isQnetdReachableFromNodes(this.qnetdHost, this.preflightResults, this.selectedHostIds.length); },
    preflightReadyForBootstrap(): boolean { const haProductReady = clusterHaProductReadiness(this.preflightResults, this.selectedHostIds.length) === 'ready'; return haProductReady && this.selectedHostIds.length >= 2 && !this.preflightArchitectureMismatch && this.preflightResults.length === this.selectedHostIds.length && this.selectedHostIds.every((id) => this.preflightResults.some((result) => { const peers = result.checks?.ssh_peer_connectivity || []; return result.host_id === id && result.status === 'checked' && result.checks?.compatibility_supported && result.checks?.ha_active && result.checks?.time_synchronized && result.checks?.tools?.crm && result.checks?.tools?.crm_mon && result.checks?.tools?.['corosync-cfgtool'] && peers.length === this.selectedHostIds.length - 1 && peers.every((peer) => peer.reachable && peer.hosts_file_entry_present === true); })); },
    bootstrapUserMismatch(): boolean { const hosts = this.selectedClusterHosts; return hosts.length >= 2 && (hosts.some((host) => !host.username?.trim()) || new Set(hosts.map((host) => host.username.trim())).size > 1); },
    canStartBootstrap(): boolean { return this.clusterPlanType === 'suse-ha' && this.preflightReadyForBootstrap && this.topologyReady && this.haStackMissingHosts.length === 0 && !this.bootstrapUserMismatch; },
    qdeviceReadyForBootstrap(): boolean { return qdeviceBootstrapReady({ clusterType: this.clusterPlanType, quorumPlan: this.quorumPlan, topologyReady: this.topologyReady, selectedHostIds: this.selectedHostIds, hosts: this.selectedClusterHosts, plannedClusterName: this.plannedClusterName, preflightResults: this.preflightResults, liveClusterStatus: this.clusterStatus }); },
    initCommand(): string { return `sudo crm cluster init --name ${this.shellArg(this.plannedClusterName)}`; },
    joinCommand(): string { return clusterJoinCommand(this.selectedClusterHosts[0]); },
    qdeviceCommand(): string { return this.selectedClusterHosts[0]?.username === 'root' ? 'crm cluster init qdevice' : 'sudo crm cluster init qdevice'; },
    eligibleHosts(): Host[] { return this.hosts.filter((host) => host.status === 'ready' && host.ha?.ha_active && !host.ha?.cluster_detected); },
    preflightArchitectureMismatch(): boolean { const architectures = [...new Set(this.preflightResults.filter((item) => item.checks).map((item) => item.checks!.architecture).filter(Boolean))]; return architectures.length > 1; },
    preflightCompatibilityWarning(): string { const checked = this.preflightResults.filter((item) => item.checks).map((item) => item.checks!); if (checked.length < 2) return ''; const architectures = [...new Set(checked.map((item) => item.architecture).filter(Boolean))]; const releases = [...new Set(checked.map((item) => `${item.os_id}:${item.os_version}`).filter((item) => item !== ':'))]; const issues = [architectures.length > 1 ? this.t('clusters.architectureMismatch') : '', releases.length > 1 ? this.t('clusters.releaseMismatch') : ''].filter(Boolean); return issues.join(' '); },
    preflightHaProductWarning(): string { const status = clusterHaProductReadiness(this.preflightResults, this.selectedHostIds.length); if (status === 'mismatch') return this.t('clusters.haProductMismatch'); if (status === 'unknown') return this.t('clusters.haProductUnconfirmed'); return ''; },
  },
  methods: {
    corosyncCandidateLabel(candidate: { subnet: string; hosts: Array<{ hostName: string; interfaces: string[] }> }): string { return `${candidate.subnet} · ${candidate.hosts.map((host) => `${host.hostName}: ${host.interfaces.join(', ') || this.t('clusters.interfaceUnknown')}`).join(' / ')}`; },
    t(key: string, args?: Record<string, unknown>): string { const translate = (this as any).$store?.getters?.['i18n/t']; return translate ? translate(`kvmManager.${key}`, args) : key; },
    setupStepComplete(index: number): boolean { if (index === 0) return this.selectedHostIds.length >= 2; if (index === 1) return this.preflightComplete && this.preflightReadyForBootstrap; if (index === 2) return this.topologyReady; if (index === 3) return this.canStartBootstrap; return this.clusterHostCount > 0; },
    canVisitSetupStep(index: number): boolean { if (index <= this.setupStep) return true; if (index === 0) return true; if (index === 1) return this.selectedHostIds.length >= 2; if (index === 2) return this.preflightComplete; if (index === 3) return this.preflightComplete && this.topologyReady; if (index === 4) return this.canStartBootstrap; return false; },
    goToSetupStep(index: number) { if (index >= 0 && index < this.setupSteps.length && this.canVisitSetupStep(index)) this.setupStep = index; },
    async checkClusterAfterSetup() { this.activeSection = 'clusters'; await this.load(); },
    async load() {
      if (this.loading || this.readinessLoading) return;
      this.loading = true; this.readinessLoading = true; this.error = ''; this.readinessError = '';
      const readinessTask = this.fetchReadiness()
        .catch((error) => { this.readinessError = (error as Error).message; })
        .finally(() => { this.readinessLoading = false; });
      try {
        await Promise.all([this.fetchPermissions(), this.fetchClusterPlans(), this.fetchManagedSuseHaClusters(), this.fetchQnetdWitnesses()]);
      } catch (error) {
        this.error = `${this.t('clusters.loadError')}: ${(error as Error).message}`;
      } finally {
        this.loading = false; this.loaded = true;
      }
      void readinessTask;
    },
    async fetchQnetdWitnesses() { const response = await fetch(`${apiBase}/qnetd-witnesses`, { credentials: 'include', cache: 'no-store' }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(apiErrorDetail(body) || `API request failed (${response.status})`); this.qnetdWitnesses = Array.isArray(body) ? body : []; },
    async refreshQnetdWitness() { const witness = this.qnetdRegisteredWitness; if (!this.canManageCluster || !witness || this.qnetdWitnessRefreshLoading) return; this.qnetdWitnessRefreshLoading = true; this.qnetdWitnessError = ''; try { const response = await fetch(`${apiBase}/qnetd-witnesses/${encodeURIComponent(witness.id)}/refresh`, { method: 'POST', credentials: 'include' }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(apiErrorDetail(body) || `API request failed (${response.status})`); await this.fetchQnetdWitnesses(); } catch (error) { this.qnetdWitnessError = apiErrorDetail({ error: (error as Error).message }) || this.t('clusters.qnetdWitnessProbeFailed'); } finally { this.qnetdWitnessRefreshLoading = false; } },
    qnetdWitnessErrorKey(code: string): string { const keys: Record<string,string> = { qnetd_ssh_auth_failed: 'qnetdWitnessSshAuthFailed', qnetd_ssh_unreachable: 'qnetdWitnessSshUnreachable', qnetd_sudo_required: 'qnetdWitnessSudoRequired', qnetd_probe_failed: 'qnetdWitnessProbeFailed', qnetd_host_unsupported: 'qnetdPrepareUnsupported' }; return keys[code] || 'qnetdWitnessProbeFailed'; },
    async probeQnetdWitness() { if (!this.canManageCluster || this.qnetdWitnessProbeLoading || !this.qnetdWitnessDraft.name.trim() || !this.qnetdWitnessDraft.address.trim()) return; this.qnetdWitnessProbeLoading = true; this.qnetdWitnessError = ''; this.qnetdWitnessProbe = null; this.qnetdWitnessProbeSignature = ''; this.qnetdWitnessFingerprintSignature = ''; this.qnetdWitnessFingerprintConfirmed = false; const identitySignature = qnetdWitnessFingerprintSignature(this.qnetdWitnessDraft); try { const response = await fetch(`${apiBase}/qnetd-witnesses/fingerprint`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(qnetdWitnessFingerprintRequest(this.qnetdWitnessDraft)) }); const body = await response.json().catch(() => ({})); if (!response.ok || !body.ok || !body.fingerprint) throw new Error(body.error_code ? this.t(`clusters.${this.qnetdWitnessErrorKey(body.error_code)}`) : apiErrorDetail(body) || `API request failed (${response.status})`); this.qnetdWitnessProbe = { fingerprint: body.fingerprint }; this.qnetdWitnessFingerprintSignature = identitySignature; } catch (error) { this.qnetdWitnessError = apiErrorDetail({ error: (error as Error).message }) || this.t('clusters.qnetdWitnessProbeFailed'); } finally { this.qnetdWitnessProbeLoading = false; } },
    async verifyQnetdWitness() { if (!this.canManageCluster || !this.qnetdWitnessFingerprintIsCurrent || !this.qnetdWitnessFingerprintConfirmed || !this.qnetdWitnessDraft.username.trim() || !this.qnetdWitnessDraft.password || this.qnetdWitnessProbeLoading) return; this.qnetdWitnessProbeLoading = true; this.qnetdWitnessError = ''; this.qnetdWitnessProbeSignature = ''; const signature = JSON.stringify(this.qnetdWitnessDraft); try { const response = await fetch(`${apiBase}/qnetd-witnesses/probe`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(qnetdWitnessVerificationPayload(this.qnetdWitnessDraft, this.qnetdWitnessProbe?.fingerprint || '', this.qnetdWitnessFingerprintConfirmed)) }); const body = await response.json().catch(() => ({})); if (!response.ok || !body.ok || !body.fingerprint || !body.facts) throw new Error(body.error_code ? this.t(`clusters.${this.qnetdWitnessErrorKey(body.error_code)}`) : apiErrorDetail(body) || `API request failed (${response.status})`); this.qnetdWitnessProbe = { fingerprint: body.fingerprint, facts: body.facts }; this.qnetdWitnessProbeSignature = signature; } catch (error) { this.qnetdWitnessError = apiErrorDetail({ error: (error as Error).message }) || this.t('clusters.qnetdWitnessProbeFailed'); } finally { this.qnetdWitnessProbeLoading = false; } },
    async registerQnetdWitness() { if (!this.canManageCluster || !this.qnetdWitnessProbeIsCurrent || !this.qnetdWitnessFingerprintConfirmed || this.qnetdWitnessSaveLoading) return; this.qnetdWitnessSaveLoading = true; this.qnetdWitnessError = ''; try { const response = await fetch(`${apiBase}/qnetd-witnesses`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(qnetdWitnessVerificationPayload(this.qnetdWitnessDraft, this.qnetdWitnessProbe?.fingerprint || '', this.qnetdWitnessFingerprintConfirmed)) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(apiErrorDetail(body) || `API request failed (${response.status})`); this.qnetdHost = body.address; this.qnetdWitnessDraft = { name: '', address: '', port: 22, username: '', password: '' }; this.qnetdWitnessProbe = null; this.qnetdWitnessProbeSignature = ''; this.qnetdWitnessFingerprintSignature = ''; this.qnetdWitnessFingerprintConfirmed = false; await this.fetchQnetdWitnesses(); } catch (error) { this.qnetdWitnessError = apiErrorDetail({ error: (error as Error).message }) || this.t('clusters.qnetdWitnessProbeFailed'); } finally { this.qnetdWitnessSaveLoading = false; } },
    async deleteQnetdWitness() { const witness = this.qnetdRegisteredWitness; if (!this.canManageCluster || !witness || this.qnetdWitnessDeleteLoading) return; this.qnetdWitnessDeleteLoading = true; this.qnetdWitnessError = ''; try { const response = await fetch(`${apiBase}/qnetd-witnesses/${encodeURIComponent(witness.id)}`, { method: 'DELETE', credentials: 'include' }); if (!response.ok) { const body = await response.json().catch(() => ({})); throw new Error(apiErrorDetail(body) || `API request failed (${response.status})`); } this.qnetdWitnessDeleteReview = false; this.qnetdPrepareResult = null; await this.fetchQnetdWitnesses(); } catch (error) { this.qnetdWitnessError = apiErrorDetail({ error: (error as Error).message }) || this.t('clusters.qnetdWitnessProbeFailed'); } finally { this.qnetdWitnessDeleteLoading = false; } },
    async prepareQnetdWitnessPackage() { const witness = this.qnetdRegisteredWitness; if (!this.canManageCluster || !witness || !this.qnetdWitnessEligible || this.qnetdPrepareLoading) return; this.qnetdPrepareLoading = true; this.qnetdPrepareError = ''; this.qnetdPrepareResult = null; try { if (!await this.saveClusterPlan()) throw new Error(this.plansError || this.t('clusters.qnetdPreparePlanChanged')); const response = await fetch(`${apiBase}/clusters/plans/${encodeURIComponent(this.currentPlanId)}/qnetd/prepare-witness`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ witness_id: witness.id }) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(apiErrorDetail(body) || `API request failed (${response.status})`); const job = await this.trackOperationJob(body, (progress) => { this.qnetdPrepareResult = (progress as QnetdPackageResult[])[0] || null; }); this.qnetdPrepareResult = (job.results[0] as QnetdPackageResult) || null; this.qnetdPrepareReview = false; await Promise.all([this.fetchQnetdWitnesses(), this.fetchReadiness()]); await this.runPreflight(); } catch (error) { this.qnetdPrepareError = apiErrorDetail({ error: (error as Error).message }) || this.t('clusters.qnetdPrepareFailed'); } finally { this.qnetdPrepareLoading = false; } },
