    openConstraintEditor(action: ConstraintEditor['action']) { this.constraintMutationError = ''; this.constraintMutationMessage = ''; this.constraintEditor = { action, constraint_id: '', resource: '', other_resource: '', node: '', score: action === 'create_order' ? '' : 'INFINITY', order_kind: 'Mandatory' }; },
    changeConstraintType(event: Event) { const action = (event.target as HTMLSelectElement).value as ConstraintEditor['action']; if (!['create_location','create_order','create_colocation'].includes(action)) return; this.openConstraintEditor(action); },
    prepareConstraintMutation() { if (!this.constraintEditor) return; const value = this.constraintEditor; if (!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/.test(value.constraint_id) || !value.resource) { this.constraintMutationError = this.t('clusters.constraintInvalid'); return; } if (value.action !== 'create_location' && (!value.other_resource || value.other_resource === value.resource)) { this.constraintMutationError = this.t('clusters.constraintInvalid'); return; } if (value.action === 'create_location' && !value.node) { this.constraintMutationError = this.t('clusters.constraintInvalid'); return; } if (value.action !== 'create_order' && value.score !== 'INFINITY' && value.score !== '-INFINITY' && !/^-?\d{1,9}$/.test(value.score)) { this.constraintMutationError = this.t('clusters.constraintInvalid'); return; } this.pendingConstraintMutation = { ...value }; this.constraintMutationError = ''; this.constraintMutationMessage = ''; },
    constraintId(item: string): string { const parts = item.trim().split(/\s+/); return ['location','order','colocation'].includes(parts[0]) ? (parts[1] || '') : (parts[0] || ''); },
    prepareConstraintDelete(item: string) { const constraint_id = this.constraintId(item); if (!constraint_id) return; this.constraintEditor = null; this.pendingConstraintMutation = { action: 'delete', constraint_id }; this.constraintMutationError = ''; this.constraintMutationMessage = ''; },
    async runConstraintMutation() { if (!this.pendingConstraintMutation || !this.activeClusterHostId || !this.canManageCluster) return; const payload = this.pendingConstraintMutation; this.constraintMutationBusy = true; this.constraintMutationError = ''; this.constraintMutationMessage = ''; try { const response = await fetch(`${apiBase}/clusters/${encodeURIComponent(this.activeClusterHostId)}/constraints/config`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(apiErrorDetail(body) || `API request failed (${response.status})`); this.constraintMutationMessage = body.message || this.t('clusters.constraintMutationSucceeded'); this.pendingConstraintMutation = null; this.constraintEditor = null; await this.fetchClusterStatus(); await this.fetchClusterDiagnostics(); } catch (error) { this.constraintMutationError = (error as Error).message; } finally { this.constraintMutationBusy = false; } },
    async runPreflight(hostIds?: unknown) { const qnetdHost = !Array.isArray(hostIds) && this.quorumPlan === 'qdevice' ? this.qnetdHost : ''; const payload = clusterPreflightPayload(hostIds, this.selectedHostIds, qnetdHost); if (payload.host_ids.length < 2) { this.preflightError = this.t('clusters.selectAtLeastTwo'); return; } this.preflightLoading = true; this.preflightError = ''; this.preflightResults = []; try { const response = await fetch(`${apiBase}/clusters/preflight`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); const body: unknown = await response.json().catch(() => ({})); if (!response.ok) { const detail = apiErrorDetail(body); if (isPreflightHostListValidationError(detail)) { const received = preflightHostListReceivedType(detail, response.headers.get('X-KVM-Preflight-Host-Ids-Type') || ''); const apiVersion = response.headers.get('X-KVM-API-Version') || ''; const message = received ? this.t('clusters.preflightHostListRejected', { received }) : this.t('clusters.preflightHostListRejectedUnknown'); throw new Error(apiVersion ? `${message} ${this.t('clusters.preflightApiVersion', { version: apiVersion })}` : message); } throw new Error(detail || `API request failed (${response.status})`); } if (!Array.isArray(body)) throw new Error(apiErrorDetail(body) || `Unexpected preflight response (${response.status})`); this.preflightResults = body.map((item: unknown) => { if (!item || typeof item !== 'object') return item as PreflightResult; const result = item as PreflightResult; return { ...result, error: result.error == null ? undefined : apiErrorDetail({ error: result.error }) || 'The host returned an unreadable preflight error.' }; }); } catch (error) { this.preflightError = apiErrorDetail({ error: (error as Error).message }) || this.t('clusters.preflightError'); } finally { this.preflightLoading = false; } },
    templateEvaluation(templateId: string): { fit: string; tone: string; requirements: { key: string; text: string; ok: boolean | null }[]; manual: string[]; hostChecks: { name: string; ok: boolean; reviewRequired?: boolean; evidence: string[]; nextSteps: string[] }[] } {
      const selected = this.selectedTemplateHosts;
      const results = selected.map((host) => this.preflightResults.find((result) => result.host_id === host.id));
      const checked = results.length >= 2 && results.every((result) => result?.status === 'checked' && result.checks);
      const checks = results.map((result) => result?.checks).filter((item): item is PreflightChecks => Boolean(item));
      const peerConnectivityReady = areClusterPeersReachable(results, selected.length);
      const haReady = checked && checks.every((item) => item.compatibility_supported && item.ha_active && item.tools?.crm && item.tools?.crm_mon);
      const sameArch = new Set(checks.map((item) => item.architecture).filter(Boolean)).size <= 1;
      const sameRelease = new Set(checks.map((item) => `${item.os_id}:${item.os_version}`)).size <= 1;
      const timeReady = checked && checks.every((item) => item.time_synchronized === true);
      const baseReady = Boolean(haReady && sameArch && sameRelease && timeReady && peerConnectivityReady);
      const requiredAgents = clusterTemplateRequiredAgents(templateId, this.nfsStorageMode);
      const agentFit = checked && clusterTemplateAgentsPresent(templateId, checks.map((item) => item.resource_agents || []), this.nfsStorageMode);
      const applicationService = templateId === 'web' ? 'apache2' : templateId === 'nfs' ? 'nfsserver' : '';
      const applicationServiceStates = applicationService ? checks.map((item) => workloadServiceInstalled(item, applicationService)) : [];
      const applicationServiceState = applicationService ? aggregateWorkloadServiceAvailability(applicationServiceStates) : true;
      // An older API only reported active state. Treat false there as unknown,
      // because HA services are not required to run on every node.
      const applicationServiceFit = !applicationService || workloadServiceRequirementFit(applicationServiceState, Boolean(checked));
      const requirements = [
        { key: 'nodes', text: this.t('clusters.templateReqTwoNodes'), ok: selected.length >= 2 },
        { key: 'connectivity', text: this.t('clusters.templateReqConnectivity'), ok: checked ? peerConnectivityReady : results.some((result) => result?.status === 'error') ? false : null },
        { key: 'ha', text: this.t('clusters.templateReqSuseHa'), ok: checked ? Boolean(haReady) : null },
        { key: 'compatibility', text: this.t('clusters.templateReqCompatibility'), ok: checked ? Boolean(checks.every((item) => item.compatibility_supported) && sameArch && sameRelease) : null },
        { key: 'tools', text: this.t('clusters.templateReqTools'), ok: checked ? Boolean(checks.every((item) => item.tools?.crm && item.tools?.crm_mon)) : null },
        { key: 'time', text: this.t('clusters.templateReqTimeSync'), ok: checked ? Boolean(timeReady) : null },
        { key: 'agents', text: this.t('clusters.templateReqAgents', { agents: requiredAgents.join(', ') }), ok: checked ? agentFit : null },
        ...(templateId === 'vm' ? [{ key: 'pool', text: this.t('clusters.templateReqLibvirtStorage', { count: (checks.length ? Math.min(...checks.map((item) => item.libvirt_pools?.length || 0)) : 0) }), ok: checked ? checks.every((item) => Boolean(item.libvirt_pools?.length)) : null }] : []),
        ...(applicationService ? [{ key: 'app', text: this.t(templateId === 'web' ? 'clusters.templateReqApache' : 'clusters.templateReqNfsServer'), ok: checked ? applicationServiceState : null }] : []),
      ];
      const manual = [this.t('clusters.templateReqFencing'), this.t('clusters.templateReqNetwork'), this.t('clusters.templateReqQuorum')];
      if (templateId === 'vm') manual.push(this.t('clusters.templateReqVmStorage'));
      if (templateId === 'service') manual.push(this.t('clusters.templateReqApplication'));
      if (templateId === 'web') manual.push(this.t('clusters.templateReqWebConfig'));
      if (templateId === 'nfs') manual.push(this.t(`clusters.templateReqNfsStorage_${this.nfsStorageMode}`), this.t('clusters.templateReqNfsStorageSafety'));
