          this.t(facts.ha_active ? 'clusters.templateStatusHaOk' : 'clusters.templateStatusHaMissing'),
          this.t(facts.time_synchronized ? 'clusters.templateStatusTimeOk' : 'clusters.templateStatusTimeMissing'),
          this.t('clusters.templateStatusPeerEvidence', { count: peerChecks.filter((peer) => peer.reachable).length, total: Math.max(0, selected.length - 1) }),
          this.t('clusters.templateStatusAgentEvidence', { count: (facts.resource_agents || []).filter((agent) => requiredAgents.includes(agent)).length, total: requiredAgents.length }),
          ...(templateId === 'vm' ? [this.t('clusters.templateStatusPoolEvidence', { pools: (facts.libvirt_pool_details || []).map((pool) => `${pool.name} (${pool.type || 'unknown'}${pool.source_path ? ` · ${pool.source_path}` : ''}${pool.source_hosts?.length ? ` · ${pool.source_hosts.join(', ')}` : ''})`).join('; ') || this.t('clusters.noneDetected') })] : []),
          ...(applicationService ? [this.t(serviceInstalled === true ? 'clusters.templateStatusAppInstalled' : serviceInstalled === false ? 'clusters.templateStatusAppMissing' : 'clusters.templateStatusAppUnknown', { service: applicationService, state: facts.workload_service_units?.[applicationService]?.active || 'unknown' })] : []),
        ] : [result?.error || this.t('clusters.templateStatusNoPreflight')]).map((item) => String(item));
        return { name: host?.hostname || host?.name || result?.host_name || '', ok, reviewRequired: serviceFit === 'review_required', evidence, nextSteps };
      }) : [];
      let fit = 'not_checked';
      if (selected.length < 2) fit = 'select_hosts';
      else if (this.preflightResults.length) {
